def draw_polyline_labelled(image, points, color, thickness=2, closed=True, label_prefix=None):
    pts = point_list_or_none(points)
    if not pts:
        return
    arr = np.round(np.asarray(pts, dtype=float)).astype(np.int32).reshape(-1, 1, 2)
    cv2.polylines(image, [arr], closed, color, thickness, cv2.LINE_AA)
    if label_prefix:
        for idx, point in enumerate(arr.reshape(-1, 2)):
            cv2.putText(
                image,
                f"{label_prefix}{idx}",
                (int(point[0]) + 3, int(point[1]) - 3),
                cv2.FONT_HERSHEY_SIMPLEX,
                0.34,
                color,
                1,
                cv2.LINE_AA,
            )


def draw_center_cross(image, point, color, size=8, thickness=2):
    p = point_or_none(point)
    if p is None:
        return
    x, y = int(round(float(p[0]))), int(round(float(p[1])))
    cv2.line(image, (x - size, y), (x + size, y), color, thickness, cv2.LINE_AA)
    cv2.line(image, (x, y - size), (x, y + size), color, thickness, cv2.LINE_AA)


def save_grasp_hull_graphic_audit(rgb_snapshot, hull_result):
    if rgb_snapshot is None or not hull_result:
        return None
    try:
        image = np.asarray(rgb_snapshot).copy()
        h, w = image.shape[:2]
        draw_polyline_labelled(image, hull_result.get("image_bottle_hull_px"), (255, 255, 0), 2, True, "B")
        bbox = hull_result.get("bottle_bbox_xyxy")
        if bbox and len(bbox) >= 4:
            x1, y1, x2, y2 = [int(round(float(v))) for v in bbox[:4]]
            cv2.rectangle(image, (x1, y1), (x2, y2), (0, 255, 0), 2, cv2.LINE_AA)
        draw_polyline_labelled(image, hull_result.get("contact_region_hull_px"), (255, 0, 255), 2, True, "C")
        debug = hull_result.get("contact_region_debug_geometry") or {}
        draw_polyline_labelled(image, debug.get("left_contact_patch_polygon"), (255, 80, 255), 1, True, "L")
        draw_polyline_labelled(image, debug.get("right_contact_patch_polygon"), (255, 80, 255), 1, True, "R")
        draw_polyline_labelled(image, debug.get("magenta_band_polygon"), (190, 0, 255), 1, True, "M")
        contacts = hull_result.get("contact_points_px") or {}
        for name, color in (("left", (255, 40, 40)), ("right", (40, 140, 255))):
            p = point_or_none(contacts.get(name))
            if p is not None:
                cv2.circle(image, (int(round(p[0])), int(round(p[1]))), 5, color, -1, cv2.LINE_AA)
                cv2.circle(image, (int(round(p[0])), int(round(p[1]))), 7, (255, 255, 255), 1, cv2.LINE_AA)
                cv2.putText(image, name[0].upper(), (int(round(p[0])) + 7, int(round(p[1])) + 4), cv2.FONT_HERSHEY_SIMPLEX, 0.45, color, 1, cv2.LINE_AA)
        draw_center_cross(image, contacts.get("object_center"), (255, 255, 255), 8, 2)
        labels = [
            f"lock_frame_id: {hull_result.get('lock_frame_id')}",
            f"image: {w}x{h}",
            f"bottle_hull_source: {hull_result.get('image_bottle_hull_source')}",
            f"contact_hull_source: {hull_result.get('contact_region_hull_source')}",
        ]
        y = 18
        for text in labels:
            cv2.putText(image, text, (8, y), cv2.FONT_HERSHEY_SIMPLEX, 0.45, (0, 0, 0), 3, cv2.LINE_AA)
            cv2.putText(image, text, (8, y), cv2.FONT_HERSHEY_SIMPLEX, 0.45, (255, 255, 255), 1, cv2.LINE_AA)
            y += 18
        path = OUTPUT_DIR / "grasp_hull_graphic_audit.jpg"
        cv2.imwrite(str(path), cv2.cvtColor(image, cv2.COLOR_RGB2BGR), [int(cv2.IMWRITE_JPEG_QUALITY), 90])
        return str(path)
    except Exception:
        return None


def finger_quality_signature(report):
    report = report or {}
    finger = report.get("finger_detection") or {}
    if finger.get("finger_detection_status") != "BOTH_FINGERS_DETECTED":
        return None
    if int(finger.get("finger_stable_frames", 0) or 0) < FINGER_STABLE_FRAMES_REQUIRED:
        return None
    lock_frame = ((report.get("target_lock") or {}).get("lock_frame_id"))
    left = point_or_none(finger.get("left_finger_contact_px"))
    right = point_or_none(finger.get("right_finger_contact_px"))
    if left is None or right is None:
        return None
    left_key = tuple(int(round(float(v) / 4.0)) for v in left[:2])
    right_key = tuple(int(round(float(v) / 4.0)) for v in right[:2])
    return (lock_frame, left_key, right_key)


def actual_contact_quality_signature(report):
    report = report or {}
    lock_frame = ((report.get("target_lock") or {}).get("lock_frame_id"))
    gripper = (
        report.get("gripper_contact_detection")
        or report.get("detected_gripper_contact")
        or report.get("gripper_detection")
        or {}
    )
    gripper_status = gripper.get("gripper_detection_status") or gripper.get("status")
    if gripper and gripper_status in {"BOTH_GRIPPERS_DETECTED", "BOTH_CONTACTS_DETECTED", "VALID", "TRACKING"}:
        left = first_point(gripper.get("left_contact_px"), gripper.get("left_gripper_contact_px"))
        right = first_point(gripper.get("right_contact_px"), gripper.get("right_gripper_contact_px"))
        left_depth = first_number(gripper.get("left_contact_depth_mm"), gripper.get("left_depth_mm"))
        right_depth = first_number(gripper.get("right_contact_depth_mm"), gripper.get("right_depth_mm"))
        if left is not None and right is not None and left_depth is not None and right_depth is not None:
            left_key = tuple(int(round(float(v) / 4.0)) for v in left[:2])
            right_key = tuple(int(round(float(v) / 4.0)) for v in right[:2])
            return ("detected_gripper", lock_frame, left_key, right_key)
    finger_signature = finger_quality_signature(report)
    if finger_signature is not None:
        return ("detected_finger",) + tuple(finger_signature)
    return None


def save_grasp_hull_overlay(rgb_snapshot, hull_result):
    if rgb_snapshot is None or not hull_result:
        return None
    try:
        image = np.asarray(rgb_snapshot).copy()
        hull_result["overlay_image_shape"] = list(image.shape)
        hull_result["overlay_coordinate_frame"] = "full_image_px"
        hull_result["overlay_coordinates_scaled_before_drawing"] = False
        bottle_hull = hull_result.get("image_bottle_hull_px")
        contact_hull = hull_result.get("contact_region_hull_px")
        if bottle_hull:
            cv2.polylines(image, [np.round(np.asarray(bottle_hull, dtype=float)).astype(np.int32)], True, (255, 255, 0), 2, cv2.LINE_AA)
        if contact_hull:
            cv2.polylines(image, [np.round(np.asarray(contact_hull, dtype=float)).astype(np.int32)], True, (255, 0, 255), 2, cv2.LINE_AA)
        path = OUTPUT_DIR / "latest_grasp_hulls_overlay.jpg"
        cv2.imwrite(str(path), cv2.cvtColor(image, cv2.COLOR_RGB2BGR), [int(cv2.IMWRITE_JPEG_QUALITY), 82])
        audit_path = save_grasp_hull_graphic_audit(rgb_snapshot, hull_result)
        if audit_path:
            hull_result["grasp_hull_graphic_audit_path"] = audit_path
        return str(path)
    except Exception:
        return None


def median_filter_values(values, window=5):
    arr = np.asarray(values, dtype=float).reshape(-1)
    if arr.size == 0:
        return arr
    radius = max(0, int(window) // 2)
    if radius <= 0:
        return arr
    out = np.empty_like(arr)
    for idx in range(arr.size):
        lo = max(0, idx - radius)
        hi = min(arr.size, idx + radius + 1)
        out[idx] = float(np.median(arr[lo:hi]))
    return out


def polygon_depth_stats(depth_snapshot, polygon, image_shape):
    pts = point_list_or_none(polygon)
    if depth_snapshot is None or not pts or len(pts) < 3:
        return {
            "depth_status": "visual_only",
            "median_mm": None,
            "std_mm": None,
            "valid_ratio": None,
            "sample_count": 0,
        }
    try:
        depth = np.asarray(depth_snapshot)
        if depth.ndim != 2:
            return {
                "depth_status": "invalid_depth_frame",
                "median_mm": None,
                "std_mm": None,
                "valid_ratio": 0.0,
                "sample_count": 0,
            }
        dh, dw = depth.shape[:2]
        ih, iw = image_shape[:2]
        poly = np.asarray(pts, dtype=np.float32)
        if (dh, dw) != (ih, iw):
            sx = float(dw) / max(float(iw), 1.0)
            sy = float(dh) / max(float(ih), 1.0)
            poly = poly * np.asarray([sx, sy], dtype=np.float32)
        mask = np.zeros((dh, dw), dtype=np.uint8)
        cv2.fillPoly(mask, [np.round(poly).astype(np.int32).reshape(-1, 1, 2)], 255)
        values = depth[mask > 0]
        total = int(values.size)
        if total <= 0:
            return {
                "depth_status": "empty_patch",
                "median_mm": None,
                "std_mm": None,
                "valid_ratio": 0.0,
                "sample_count": 0,
            }
        values = values[np.isfinite(values) & (values > 0)]
        if values.size <= 0:
            return {
                "depth_status": "missing_depth",
                "median_mm": None,
                "std_mm": None,
                "valid_ratio": 0.0,
                "sample_count": 0,
            }
        return {
            "depth_status": "valid",
            "median_mm": float(np.median(values)),
            "std_mm": float(np.std(values)),
            "valid_ratio": float(values.size) / float(max(total, 1)),
            "sample_count": int(values.size),
        }
    except Exception as exc:
        return {
            "depth_status": f"depth_error:{exc}",
            "median_mm": None,
            "std_mm": None,
            "valid_ratio": 0.0,
            "sample_count": 0,
        }


def contact_patch_visualization_from_mask(hull_result, image_shape, depth_snapshot=None):
    image_shape = tuple(image_shape[:2])
    h, w = image_shape
    bottle_hull = point_list_or_none(hull_result.get("image_bottle_hull_px"))
    contacts = hull_result.get("contact_points_px") or {}
    left_input = point_or_none(contacts.get("left"))
    right_input = point_or_none(contacts.get("right"))
    object_center = point_or_none(contacts.get("object_center"))
    if object_center is None:
        object_center = polygon_center_from_points(bottle_hull) if bottle_hull else None
    debug_geometry = hull_result.get("contact_region_debug_geometry") or {}
    base_left_patch = point_list_or_none(debug_geometry.get("left_contact_patch_polygon"))
    base_right_patch = point_list_or_none(debug_geometry.get("right_contact_patch_polygon"))

    result = {
        "contact_patch_status": "invalid",
        "contact_hull_reason": None,
        "contact_source": hull_result.get("contact_source") or hull_result.get("quality_input_source") or "unavailable",
        "contact_source_confidence": None,
        "contact_source_reason": None,
        "left_contact_status": "unavailable",
        "right_contact_status": "unavailable",
        "locked_bottle_mask_hull_px": bottle_hull,
        "current_live_bottle_mask_hull_px": hull_result.get("current_live_bottle_hull_px"),
        "bottle_mask_hull_px": bottle_hull,
        "bottle_hull_area_px": polygon_area_px(bottle_hull),
        "bottle_mask_valid": bool(bottle_hull and len(bottle_hull) >= 3),
        "quality_input_left_contact_px": None if left_input is None else json_safe(left_input.tolist()),
        "quality_input_right_contact_px": None if right_input is None else json_safe(right_input.tolist()),
        "quality_input_contact_source": hull_result.get("quality_input_source") or hull_result.get("contact_source"),
        "quality_input_contact_patch_height_px": None,
        "quality_input_contact_depth_status": None,
        "matrix_valid_for_current_pose": not bool(
            hull_result.get("matrix_stale_due_to_invalidation")
            or hull_result.get("matrix_stale_due_to_motion")
        ),
        "matrix_stale_due_to_motion": bool(hull_result.get("matrix_stale_due_to_motion")),
    }

    if left_input is not None and right_input is not None:
        result["contact_source_confidence"] = first_number(
            hull_result.get("contact_confidence_left"),
            hull_result.get("contact_confidence_right"),
            0.0,
        )
    if not bottle_hull:
        result["contact_hull_reason"] = "missing_bottle_mask_hull"
        return result
    if object_center is None:
        result["contact_hull_reason"] = "missing_object_center"
        return result

    mask = np.zeros((h, w), dtype=np.uint8)
    hull_arr = np.round(np.asarray(bottle_hull, dtype=float)).astype(np.int32).reshape(-1, 1, 2)
    cv2.fillPoly(mask, [hull_arr], 255)
    bottle_bbox = polygon_bbox_from_points(bottle_hull)
    if not bottle_bbox:
        result["contact_hull_reason"] = "invalid_bottle_hull_bbox"
        return result
    bx1, by1, bx2, by2 = bottle_bbox
    bottle_height = max(float(by2 - by1), 1.0)
    bottle_width = max(float(bx2 - bx1), 1.0)
    input_y_values = [p[1] for p in (left_input, right_input) if p is not None]
    grasp_y = float(np.median(input_y_values)) if input_y_values else float(object_center[1])
    patch_height = None
    for patch in (base_left_patch, base_right_patch):
        bbox = polygon_bbox_from_points(patch)
        if bbox:
            patch_height = max(float(bbox[3] - bbox[1]), patch_height or 0.0)
    if patch_height is None or patch_height <= 2.0:
        patch_height = float(np.clip(0.22 * bottle_height, 28.0, 74.0))
    patch_width = None
    for patch in (base_left_patch, base_right_patch):
        bbox = polygon_bbox_from_points(patch)
        if bbox:
            patch_width = max(float(bbox[2] - bbox[0]), patch_width or 0.0)
    if patch_width is None or patch_width <= 1.0:
        patch_width = float(np.clip(0.055 * bottle_width, 8.0, 22.0))

    y1 = int(max(0, round(grasp_y - patch_height * 0.5)))
    y2 = int(min(h - 1, round(grasp_y + patch_height * 0.5)))
    rows = []
    left_xs = []
    right_xs = []
    for y in range(y1, y2 + 1):
        xs = np.flatnonzero(mask[y] > 0)
        if xs.size < 3:
            continue
        rows.append(float(y))
        left_xs.append(float(np.percentile(xs, 5)))
        right_xs.append(float(np.percentile(xs, 95)))

    expected_rows = max(1, y2 - y1 + 1)
    valid_ratio = float(len(rows)) / float(expected_rows)
    if len(rows) < 4:
        result.update({
            "contact_patch_valid_ratio": valid_ratio,
            "contact_hull_reason": "too_few_mask_rows_at_grasp_height",
        })
        return result

    rows_arr = np.asarray(rows, dtype=float)
    left_arr = median_filter_values(left_xs, 5)
    right_arr = median_filter_values(right_xs, 5)
    sample_count = min(24, len(rows_arr))
    sample_idx = np.unique(np.linspace(0, len(rows_arr) - 1, sample_count).astype(int))
    boundary_left = np.column_stack([left_arr[sample_idx], rows_arr[sample_idx]])
    boundary_right = np.column_stack([right_arr[sample_idx], rows_arr[sample_idx]])

    left_inward = boundary_left + np.asarray([patch_width, 0.0])
    right_inward = boundary_right - np.asarray([patch_width, 0.0])
    left_polygon = np.vstack([boundary_left, left_inward[::-1]])
    right_polygon = np.vstack([boundary_right, right_inward[::-1]])
    left_center = np.asarray([float(np.median(left_arr)), float(np.median(rows_arr))])
    right_center = np.asarray([float(np.median(right_arr)), float(np.median(rows_arr))])
    contact_hull_points = np.vstack([left_polygon, right_polygon, left_center.reshape(1, 2), right_center.reshape(1, 2)])
    contact_hull = convex_hull_points_2d(contact_hull_points, max_points=32)
    contact_hull_area = polygon_area_px(contact_hull)
    bottle_hull_area = max(result["bottle_hull_area_px"], 1.0)
    left_inside = point_inside_polygon(left_center, bottle_hull)
    right_inside = point_inside_polygon(right_center, bottle_hull)
    left_correct_side = bool(left_center[0] < float(object_center[0]))
    right_correct_side = bool(right_center[0] > float(object_center[0]))
    contact_hull_valid = bool(
        contact_hull
        and left_inside
        and right_inside
        and left_correct_side
        and right_correct_side
        and valid_ratio >= 0.55
        and contact_hull_area > 5.0
        and contact_hull_area < bottle_hull_area * 0.85
    )
    validation_reasons = []
    if not left_inside:
        validation_reasons.append("left_contact_center_outside_bottle_mask")
    if not right_inside:
        validation_reasons.append("right_contact_center_outside_bottle_mask")
    if not left_correct_side:
        validation_reasons.append("left_contact_not_left_of_object_center")
    if not right_correct_side:
        validation_reasons.append("right_contact_not_right_of_object_center")
    if valid_ratio < 0.55:
        validation_reasons.append("contact_patch_valid_ratio_too_low")
    if contact_hull_area <= 5.0:
        validation_reasons.append("contact_hull_area_too_small")
    if contact_hull_area >= bottle_hull_area * 0.85:
        validation_reasons.append("contact_hull_area_unreasonable")

    left_depth = polygon_depth_stats(depth_snapshot, left_polygon, image_shape)
    right_depth = polygon_depth_stats(depth_snapshot, right_polygon, image_shape)
    depth_status = "visual_only"
    depth_consistent = None
    if left_depth.get("depth_status") == "valid" and right_depth.get("depth_status") == "valid":
        depth_delta = abs(float(left_depth["median_mm"]) - float(right_depth["median_mm"]))
        depth_consistent = bool(
            (left_depth.get("valid_ratio") or 0.0) >= 0.35
            and (right_depth.get("valid_ratio") or 0.0) >= 0.35
            and depth_delta <= 140.0
        )
        depth_status = "valid" if depth_consistent else "inconsistent_depth"
        if not depth_consistent:
            validation_reasons.append("contact_depth_inconsistent")
    elif depth_snapshot is not None:
        depth_status = "invalid_depth"
        validation_reasons.append("contact_depth_invalid")

    left_input_delta = None
    right_input_delta = None
    if left_input is not None:
        left_input_delta = float(np.linalg.norm(left_input - left_center))
    if right_input is not None:
        right_input_delta = float(np.linalg.norm(right_input - right_center))
    input_matches = bool(
        left_input_delta is not None
        and right_input_delta is not None
        and left_input_delta <= 8.0
        and right_input_delta <= 8.0
    )
    if not input_matches:
        validation_reasons.append("quality_input_points_differ_from_mask_patch_centers")

    result.update({
        "contact_patch_status": "valid" if contact_hull_valid else "invalid",
        "contact_hull_reason": "valid" if contact_hull_valid else ",".join(validation_reasons or ["validation_failed"]),
        "left_contact_boundary_px": point_list_or_none(boundary_left, max_points=32),
        "right_contact_boundary_px": point_list_or_none(boundary_right, max_points=32),
        "left_contact_patch_polygon_px": point_list_or_none(left_polygon, max_points=48),
        "right_contact_patch_polygon_px": point_list_or_none(right_polygon, max_points=48),
        "left_contact_center_px": json_safe(left_center.tolist()),
        "right_contact_center_px": json_safe(right_center.tolist()),
        "contact_patch_height_px": float(patch_height),
        "contact_patch_width_px": float(patch_width),
        "contact_patch_valid_ratio": valid_ratio,
        "left_contact_depth_median_mm": left_depth.get("median_mm"),
        "right_contact_depth_median_mm": right_depth.get("median_mm"),
        "left_contact_depth_std_mm": left_depth.get("std_mm"),
        "right_contact_depth_std_mm": right_depth.get("std_mm"),
        "left_contact_depth_valid_ratio": left_depth.get("valid_ratio"),
        "right_contact_depth_valid_ratio": right_depth.get("valid_ratio"),
        "contact_depth_consistent": depth_consistent,
        "contact_depth_status": depth_status,
        "left_contact_depth_stats": left_depth,
        "right_contact_depth_stats": right_depth,
        "left_contact_status": "valid" if left_inside and left_correct_side else "invalid",
        "right_contact_status": "valid" if right_inside and right_correct_side else "invalid",
        "locked_contact_hull_px": contact_hull,
        "current_live_contact_hull_px": contact_hull,
        "contact_hull_vertices_px": contact_hull,
        "contact_hull_area_px": contact_hull_area,
        "contact_hull_valid": contact_hull_valid,
        "quality_input_contact_patch_height_px": float(patch_height),
        "quality_input_contact_depth_status": depth_status,
        "quality_input_left_delta_from_display_center_px": left_input_delta,
        "quality_input_right_delta_from_display_center_px": right_input_delta,
        "quality_input_matches_displayed_contact_centers": input_matches,
    })
    return result


def draw_label_with_halo(image, text, origin, scale=0.48, color=(255, 255, 255), thickness=1):
    x, y = int(round(origin[0])), int(round(origin[1]))
    cv2.putText(image, text, (x, y), cv2.FONT_HERSHEY_SIMPLEX, scale, (0, 0, 0), thickness + 2, cv2.LINE_AA)
    cv2.putText(image, text, (x, y), cv2.FONT_HERSHEY_SIMPLEX, scale, color, thickness, cv2.LINE_AA)


def draw_dashed_circle(image, center, radius, color, thickness=2, segments=36, gap_every=2):
    cx, cy = float(center[0]), float(center[1])
    radius = float(radius)
    for idx in range(int(segments)):
        if idx % int(gap_every) == 1:
            continue
        a0 = 2.0 * math.pi * float(idx) / float(segments)
        a1 = 2.0 * math.pi * float(idx + 0.7) / float(segments)
        p0 = (int(round(cx + radius * math.cos(a0))), int(round(cy + radius * math.sin(a0))))
        p1 = (int(round(cx + radius * math.cos(a1))), int(round(cy + radius * math.sin(a1))))
        cv2.line(image, p0, p1, color, thickness, cv2.LINE_AA)


def epsilon_visual_style(hull_result):
    score = first_number(hull_result.get("epsilon_score"), hull_result.get("normalized_quality_score"))
    raw_epsilon = first_number(hull_result.get("raw_epsilon"), hull_result.get("epsilon"), hull_result.get("epsilon_ball_radius"))
    if score is None and raw_epsilon is not None:
        # Operator-facing display scale: full score at epsilon >= 0.05, aligned
        # with the GOOD/OK/WEAK label thresholds (quality_label_from_epsilon) and
        # wrench_safety. Distinct from the pre-grasp candidate-ranking scale
        # (0.20); see docs/final_epsilon_consistency_report.md.
        score = float(np.clip(100.0 * raw_epsilon / 0.05, 0.0, 100.0))
    if score is None:
        score = 0.0
    score = float(np.clip(score, 0.0, 100.0))
    label = str(hull_result.get("quality_label_display") or hull_result.get("quality_label") or "").upper()
    source = "epsilon_score"
    if "INVALID" in label or "FAILED" in label:
        score = 0.0
        source = "quality_label_invalid"
    elif "WEAK" in label or "NOT" in label:
        score = min(score, 24.0)
        source = "quality_label_weak"
    elif "MEDIUM" in label or "OK" in label or "ADJUST" in label:
        score = min(max(score, 35.0), 62.0)
        source = "quality_label_medium"
    elif "GOOD" in label or "READY" in label:
        score = max(score, 72.0)
        source = "quality_label_good"
    radius = float(np.clip(12.0 + (score / 100.0) * 48.0, 12.0, 60.0))
    if score >= 70.0:
        color = (40, 220, 70)
        band = "strong"
    elif score >= 35.0:
        color = (0, 215, 255)
        band = "medium"
    else:
        color = (40, 80, 255)
        band = "weak"
    return {
        "epsilon_visual_score": score,
        "epsilon_visual_radius_px": radius,
        "epsilon_visual_color_bgr": color,
        "epsilon_visual_quality_band": band,
        "epsilon_visual_mapping_source": source,
    }


def image_quality_contact_midpoint(contact_meta, contacts):
    left = point_or_none(contact_meta.get("quality_input_left_contact_px"))
    right = point_or_none(contact_meta.get("quality_input_right_contact_px"))
    source = "quality_input_contacts"
    if left is None or right is None:
        left = point_or_none(contacts.get("left"))
        right = point_or_none(contacts.get("right"))
        source = "contact_points_px"
    if left is None or right is None:
        left = point_or_none(contact_meta.get("left_contact_center_px"))
        right = point_or_none(contact_meta.get("right_contact_center_px"))
        source = "mask_contact_patch_centers"
    if left is None or right is None:
        return None, None, None, "missing_contact_pair"
    midpoint = (left + right) * 0.5
    axis = right - left
    norm = float(np.linalg.norm(axis))
    if norm > 1e-6:
        axis_unit = axis / norm
        normal_unit = np.asarray([-axis_unit[1], axis_unit[0]], dtype=float)
    else:
        axis_unit = None
        normal_unit = None
    return midpoint, axis_unit, normal_unit, source


def write_quality_overlay_variants(image_rgb, contact_image_rgb=None):
    paths = {}
    if image_rgb is None:
        return paths
    try:
        bottle_path = OUTPUT_DIR / "bottle_quality_overlay.jpg"
        cv2.imwrite(str(bottle_path), cv2.cvtColor(image_rgb, cv2.COLOR_RGB2BGR), [int(cv2.IMWRITE_JPEG_QUALITY), 92])
        paths["bottle_quality_overlay_path"] = "output/bottle_quality_overlay.jpg"
        contact_path = OUTPUT_DIR / "contact_quality_overlay.jpg"
        source = contact_image_rgb if contact_image_rgb is not None else image_rgb
        cv2.imwrite(str(contact_path), cv2.cvtColor(source, cv2.COLOR_RGB2BGR), [int(cv2.IMWRITE_JPEG_QUALITY), 92])
        paths["contact_quality_overlay_path"] = "output/contact_quality_overlay.jpg"
    except Exception as exc:
        paths["quality_overlay_variant_error"] = str(exc)
    return paths


QUALITY_ARTIFACTS = {
    "bottle_quality_overlay": "bottle_quality_overlay.jpg",
    "bottle_quality_context": "bottle_quality_context.jpg",
    "bottle_quality_closeup": "bottle_quality_closeup.jpg",
    "contact_quality_overlay": "contact_quality_overlay.jpg",
    "contact_hull_overlay": "contact_hull_overlay.jpg",
    "grasp_quality_weak_direction": "grasp_quality_bottle_mask_weak_direction.png",
    "wrench_space_3d_hull": "wrench_space_3d_hull.png",
    "wrench_space_projection": "wrench_space_projection.png",
    "wrench_space_fx_fy": "wrench_space_fx_fy.png",
    "wrench_space_fx_tau": "wrench_space_fx_tau.png",
    "wrench_space_fy_tau": "wrench_space_fy_tau.png",
    "realtime_epsilon_result": "realtime_epsilon_result.json",
    "quality_matrix_status": "realtime_wrench_matrix_status.json",
    "grasp_hulls": "realtime_grasp_hulls.json",
}


def _artifact_rel_path(name):
    filename = QUALITY_ARTIFACTS.get(name)
    return f"output/{filename}" if filename else None


def _quality_artifact_status(name):
    filename = QUALITY_ARTIFACTS.get(name)
    if not filename:
        return {"exists": False, "path": None, "mtime": None}
    path = OUTPUT_DIR / filename
    return {
        "exists": path.exists(),
        "path": f"output/{filename}",
        "mtime": path.stat().st_mtime if path.exists() else None,
    }


def _quality_image_bbox(hull_result, image_shape):
    h, w = image_shape[:2]
    points = []
    for key in (
        "image_bottle_hull_px",
        "contact_region_hull_px",
        "contact_hull_vertices_px",
        "left_contact_patch_polygon_px",
        "right_contact_patch_polygon_px",
    ):
        pts = point_list_or_none((hull_result or {}).get(key))
        if pts:
            points.extend(pts)
    bbox = (hull_result or {}).get("bottle_bbox_xyxy")
    if bbox and len(bbox) >= 4:
        try:
            x1, y1, x2, y2 = [float(v) for v in bbox[:4]]
            points.extend([[x1, y1], [x2, y2]])
        except Exception:
            pass
    if not points:
        return [0, 0, w, h]
    arr = np.asarray(points, dtype=float).reshape(-1, 2)
    x1, y1 = np.nanmin(arr, axis=0)
    x2, y2 = np.nanmax(arr, axis=0)
    bw = max(1.0, x2 - x1)
    bh = max(1.0, y2 - y1)
    margin = max(18.0, 0.22 * max(bw, bh))
    return [
        int(max(0, math.floor(x1 - margin))),
        int(max(0, math.floor(y1 - margin))),
        int(min(w, math.ceil(x2 + margin))),
        int(min(h, math.ceil(y2 + margin))),
    ]


def write_quality_context_closeup(image_rgb, hull_result):
    """Write full-scene and cropped quality presentation images."""
    paths = {}
    if image_rgb is None:
        return paths
    try:
        image = np.asarray(image_rgb)
        if image.ndim != 3:
            return paths
        context_path = OUTPUT_DIR / "bottle_quality_context.jpg"
        closeup_path = OUTPUT_DIR / "bottle_quality_closeup.jpg"
        cv2.imwrite(str(context_path), cv2.cvtColor(image, cv2.COLOR_RGB2BGR), [int(cv2.IMWRITE_JPEG_QUALITY), 92])
        x1, y1, x2, y2 = _quality_image_bbox(hull_result, image.shape)
        crop = image[y1:y2, x1:x2].copy()
        if crop.size == 0:
            crop = image.copy()
        cv2.imwrite(str(closeup_path), cv2.cvtColor(crop, cv2.COLOR_RGB2BGR), [int(cv2.IMWRITE_JPEG_QUALITY), 92])
        paths["bottle_quality_context_path"] = "output/bottle_quality_context.jpg"
        paths["bottle_quality_closeup_path"] = "output/bottle_quality_closeup.jpg"
        paths["bottle_quality_closeup_bbox_xyxy"] = [x1, y1, x2, y2]
    except Exception as exc:
        paths["quality_context_closeup_error"] = str(exc)
    return paths


def publish_quality_bundle(matrix_status, hull_result, *, status_override=None, errors=None):
    """Publish a coherent quality manifest and run-specific artifact copies."""
    compute_id = (matrix_status or {}).get("quality_compute_id") or (hull_result or {}).get("quality_compute_id")
    if not compute_id:
        compute_id = f"qm-{int(time.time() * 1000)}-{uuid.uuid4().hex[:8]}"
    matrix = dict(matrix_status or {})
    hull = dict(hull_result or {})
    compute_started_at = first_number(
        matrix.get("quality_compute_started_at"),
        hull.get("quality_compute_started_at"),
    )
    compute_started_at_ns = next(
        (
            int(value)
            for value in (
                matrix.get("quality_compute_started_at_ns"),
                hull.get("quality_compute_started_at_ns"),
            )
            if value is not None
        ),
        int(float(compute_started_at) * 1_000_000_000) if compute_started_at is not None else None,
    )
    stale = bool(
        matrix.get("quality_label_stale")
        or matrix.get("matrix_stale_due_to_invalidation")
        or matrix.get("matrix_stale_due_to_motion")
        or hull.get("quality_label_stale")
        or hull.get("matrix_stale_due_to_invalidation")
        or hull.get("matrix_stale_due_to_motion")
    )
    matrix_status_value = str(matrix.get("quality_matrix_status") or hull.get("matrix_status") or hull.get("status") or "").lower()
    bundle_status = status_override
    if not bundle_status:
        if errors or matrix_status_value in {"failed", "invalid"} or str(hull.get("status") or "").lower() == "failed":
            bundle_status = "FAILED"
        elif stale or matrix_status_value == "stale_needs_recompute":
            bundle_status = "STALE"
        else:
            bundle_status = "CURRENT"
    run_dir = OUTPUT_DIR / "quality_runs" / str(compute_id)
    run_dir.mkdir(parents=True, exist_ok=True)
    artifact_status = {}
    copy_errors = []
    for name, filename in QUALITY_ARTIFACTS.items():
        src = OUTPUT_DIR / filename
        item = _quality_artifact_status(name)
        generated_for_current_compute = bool(
            src.exists()
            and compute_started_at_ns is not None
            and int(src.stat().st_mtime_ns) >= int(compute_started_at_ns)
        )
        item["generated_for_current_compute"] = generated_for_current_compute
        item["quality_compute_started_at"] = compute_started_at
        item["quality_compute_started_at_ns"] = compute_started_at_ns
        if generated_for_current_compute:
            dst = run_dir / filename
            try:
                shutil.copy2(src, dst)
                item["run_path"] = f"output/quality_runs/{compute_id}/{filename}"
                item["compute_id"] = compute_id
                item["artifact_status"] = "current"
            except Exception as exc:
                item["artifact_status"] = "copy_failed"
                item["error"] = str(exc)
                copy_errors.append(f"{name}:{exc}")
        elif src.exists():
            item["artifact_status"] = "stale_from_previous_compute"
        else:
            item["artifact_status"] = "missing"
        artifact_status[name] = item
    all_required = [
        "bottle_quality_overlay",
        "bottle_quality_closeup",
        "contact_hull_overlay",
        "wrench_space_3d_hull",
        "wrench_space_fx_fy",
        "wrench_space_fx_tau",
        "quality_matrix_status",
    ]
    missing_required = [
        name
        for name in all_required
        if artifact_status.get(name, {}).get("generated_for_current_compute") is not True
    ]
    if missing_required and bundle_status == "CURRENT":
        bundle_status = "PARTIAL"
    if copy_errors and bundle_status == "CURRENT":
        bundle_status = "PARTIAL"
    stale_reasons = matrix.get("quality_current_mismatch_reasons") or matrix.get("matrix_stale_reasons") or hull.get("matrix_stale_reasons") or []
    manifest = {
        "quality_compute_id": compute_id,
        "quality_compute_timestamp": utc_now(),
        "quality_bundle_status": bundle_status,
        "matrix_compute_id": compute_id,
        "quality_compute_started_at": compute_started_at,
        "quality_compute_started_at_ns": compute_started_at_ns,
        "bottle_overlay_compute_id": compute_id if artifact_status.get("bottle_quality_overlay", {}).get("generated_for_current_compute") else None,
        "contact_hull_compute_id": compute_id if artifact_status.get("contact_hull_overlay", {}).get("generated_for_current_compute") else None,
        "wrench_plot_compute_id": compute_id if artifact_status.get("wrench_space_3d_hull", {}).get("generated_for_current_compute") else None,
        "fx_fy_compute_id": compute_id if artifact_status.get("wrench_space_fx_fy", {}).get("generated_for_current_compute") else None,
        "fx_tau_compute_id": compute_id if artifact_status.get("wrench_space_fx_tau", {}).get("generated_for_current_compute") else None,
        "fy_tau_compute_id": compute_id if artifact_status.get("wrench_space_fy_tau", {}).get("generated_for_current_compute") else None,
        "matrix_valid_for_current_pose": bool(bundle_status == "CURRENT"),
        "artifact_render_status": "complete" if not missing_required and not copy_errors else "partial",
        "dashboard_artifact_fresh": bool(bundle_status == "CURRENT"),
        "quality_stale_reason": "; ".join(stale_reasons) if stale_reasons else None,
        "matrix_fields": {
            "quality_matrix_status": matrix.get("quality_matrix_status"),
            "quality_label": matrix.get("quality_label"),
            "epsilon": matrix.get("raw_epsilon") or matrix.get("epsilon"),
            "epsilon_score": matrix.get("epsilon_score"),
            "force_closure": matrix.get("force_closure"),
            "contact_source": matrix.get("contact_source") or matrix.get("quality_input_source"),
            "current_action": matrix.get("current_action"),
        },
        "artifact_paths": artifact_status,
        "artifact_timestamps": {name: item.get("mtime") for name, item in artifact_status.items()},
        "errors": list(errors or []) + copy_errors,
        "missing_required_artifacts": missing_required,
        "stale_reasons": stale_reasons,
        "writer_session_id": matrix.get("writer_session_id") or hull.get("writer_session_id"),
        "lock_frame_id": matrix.get("lock_frame_id") or hull.get("lock_frame_id"),
        "lock_attempt_id": (
            matrix.get("lock_attempt_id")
            or matrix.get("attempt_id")
            or hull.get("lock_attempt_id")
            or hull.get("attempt_id")
        ),
        "bottle_target_id": matrix.get("bottle_target_id") or hull.get("bottle_target_id"),
        "locked_band_id": matrix.get("locked_band_id") or hull.get("locked_band_id"),
        "quality_baseline_role": matrix.get("quality_baseline_role") or hull.get("quality_baseline_role"),
        "quality_input_source": matrix.get("quality_input_source") or hull.get("quality_input_source"),
        "quality_contact_source_forced": bool(
            matrix.get("quality_contact_source_forced") is True
            or hull.get("quality_contact_source_forced") is True
        ),
        "baseline_frozen": bool(matrix.get("baseline_frozen") is True),
    }
    write_json(OUTPUT_DIR / "current_quality_bundle.json", manifest)
    if bundle_status == "CURRENT":
        write_json(OUTPUT_DIR / "last_valid_quality_bundle.json", manifest)
    return manifest


def save_wrench_space_convex_hull_debug_alias():
    src = OUTPUT_DIR / "wrench_space_3d_hull.png"
    dst = OUTPUT_DIR / "wrench_space_convex_hull_debug.jpg"
    if not src.exists():
        return None
    try:
        img = cv2.imread(str(src), cv2.IMREAD_COLOR)
        if img is None:
            return None
        cv2.imwrite(str(dst), img, [int(cv2.IMWRITE_JPEG_QUALITY), 92])
        return "output/wrench_space_convex_hull_debug.jpg"
    except Exception:
        return None


def save_contact_patch_debug_images(rgb_snapshot, hull_result, contact_meta, weak_image=None):
    if rgb_snapshot is None or not contact_meta:
        return {}
    paths = {}
    try:
        base = np.asarray(rgb_snapshot).copy()
        overlay_img = base.copy()
        bottle_hull = point_list_or_none(contact_meta.get("bottle_mask_hull_px"))
        if bottle_hull:
            pts = np.round(np.asarray(bottle_hull, dtype=float)).astype(np.int32).reshape(-1, 1, 2)
            cv2.polylines(overlay_img, [pts], True, (255, 230, 0), 2, cv2.LINE_AA)
        for key, color in (
            ("left_contact_patch_polygon_px", (255, 0, 255)),
            ("right_contact_patch_polygon_px", (255, 0, 255)),
        ):
            poly = point_list_or_none(contact_meta.get(key))
            if poly:
                pts = np.round(np.asarray(poly, dtype=float)).astype(np.int32).reshape(-1, 1, 2)
                patch_layer = overlay_img.copy()
                cv2.fillPoly(patch_layer, [pts], color, cv2.LINE_AA)
                overlay_img = cv2.addWeighted(patch_layer, 0.30, overlay_img, 0.70, 0)
                cv2.polylines(overlay_img, [pts], True, color, 2, cv2.LINE_AA)
        contact_hull = point_list_or_none(contact_meta.get("contact_hull_vertices_px"))
        if contact_hull:
            pts = np.round(np.asarray(contact_hull, dtype=float)).astype(np.int32).reshape(-1, 1, 2)
            cv2.polylines(overlay_img, [pts], True, (255, 255, 255), 1, cv2.LINE_AA)
            cv2.polylines(overlay_img, [pts], True, (255, 0, 255), 2, cv2.LINE_AA)
        for name in ("left", "right"):
            p = point_or_none(contact_meta.get(f"{name}_contact_center_px"))
            if p is not None:
                cv2.circle(overlay_img, (int(round(p[0])), int(round(p[1]))), 6, (255, 255, 255), -1, cv2.LINE_AA)
                cv2.circle(overlay_img, (int(round(p[0])), int(round(p[1]))), 4, (255, 0, 255), -1, cv2.LINE_AA)
        q_left = point_or_none(contact_meta.get("quality_input_left_contact_px"))
        q_right = point_or_none(contact_meta.get("quality_input_right_contact_px"))
        for label, p in (("Q-L", q_left), ("Q-R", q_right)):
            if p is not None:
                cv2.circle(overlay_img, (int(round(p[0])), int(round(p[1]))), 8, (0, 255, 255), 1, cv2.LINE_AA)
                draw_label_with_halo(overlay_img, label, (p[0] + 8, p[1] + 4), 0.38, (0, 255, 255), 1)
        draw_label_with_halo(overlay_img, "Bottle mask hull", (10, 20), 0.46, (255, 230, 0), 1)
        draw_label_with_halo(overlay_img, "Contact patch hull", (10, 40), 0.46, (255, 80, 255), 1)
        path = OUTPUT_DIR / "contact_hull_overlay.jpg"
        cv2.imwrite(str(path), cv2.cvtColor(overlay_img, cv2.COLOR_RGB2BGR), [int(cv2.IMWRITE_JPEG_QUALITY), 90])
        paths["contact_hull_overlay_path"] = "output/contact_hull_overlay.jpg"

        debug_img = base.copy()
        for key, color in (
            ("left_contact_boundary_px", (0, 255, 255)),
            ("right_contact_boundary_px", (0, 255, 255)),
        ):
            pts = point_list_or_none(contact_meta.get(key))
            if pts:
                arr = np.round(np.asarray(pts, dtype=float)).astype(np.int32)
                for idx, (x, y) in enumerate(arr):
                    cv2.circle(debug_img, (int(x), int(y)), 2, color, -1, cv2.LINE_AA)
                    if idx in {0, len(arr) - 1}:
                        draw_label_with_halo(debug_img, str(idx), (int(x) + 3, int(y) + 3), 0.32, color, 1)
        for key in ("left_contact_patch_polygon_px", "right_contact_patch_polygon_px", "contact_hull_vertices_px"):
            poly = point_list_or_none(contact_meta.get(key))
            if poly:
                pts = np.round(np.asarray(poly, dtype=float)).astype(np.int32).reshape(-1, 1, 2)
                cv2.polylines(debug_img, [pts], True, (255, 0, 255), 1, cv2.LINE_AA)
        debug_labels = [
            f"source: {contact_meta.get('contact_source')}",
            f"depth: {contact_meta.get('contact_depth_status')}",
            f"valid: {contact_meta.get('contact_hull_valid')}",
            f"reason: {contact_meta.get('contact_hull_reason')}",
        ]
        y = 20
        for text in debug_labels:
            draw_label_with_halo(debug_img, text, (10, y), 0.42, (255, 255, 255), 1)
            y += 18
        path = OUTPUT_DIR / "contact_patch_debug.jpg"
        cv2.imwrite(str(path), cv2.cvtColor(debug_img, cv2.COLOR_RGB2BGR), [int(cv2.IMWRITE_JPEG_QUALITY), 90])
        paths["contact_patch_debug_path"] = "output/contact_patch_debug.jpg"
    except Exception as exc:
        paths["contact_debug_image_error"] = str(exc)
    return paths


def write_contact_hull_debug(contact_meta, hull_result):
    payload = {
        "timestamp": utc_now(),
        "frame_id": hull_result.get("quality_matrix_frame_id"),
        "lock_frame_id": hull_result.get("lock_frame_id"),
        "writer_session_id": hull_result.get("writer_session_id"),
        "quality_compute_id": hull_result.get("quality_compute_id"),
    }
    payload.update(contact_meta or {})
    write_json(OUTPUT_DIR / "contact_hull_debug.json", payload)
    return "output/contact_hull_debug.json"


def save_grasp_quality_bottle_weak_direction_overlay(rgb_snapshot, hull_result, depth_snapshot=None):
    if rgb_snapshot is None or not hull_result:
        return None, {}
    metadata = {
        "weak_direction_overlay_path": None,
        "weak_direction_overlay_status": "invalid",
        "weak_direction_overlay_failure_reason": None,
        "weak_direction_semantics": "ANALYTIC_GRASP_RESISTANCE_NOT_OBJECT_MOTION",
        "weak_direction_is_object_motion": False,
        "operator_quality_view_includes_weak_direction_arrow": False,
        "quality_compute_id": hull_result.get("quality_compute_id"),
        "writer_session_id": hull_result.get("writer_session_id"),
        "lock_frame_id": hull_result.get("lock_frame_id"),
        "weak_direction_wrench": hull_result.get("weak_direction"),
        "weak_force_direction_px": None,
        "weak_torque_component": None,
        "bottle_mask_source": hull_result.get("image_bottle_hull_source") or hull_result.get("bottle_hull_source"),
        "contact_source": hull_result.get("contact_source"),
    }
    try:
        image = np.asarray(rgb_snapshot).copy()
        if image.ndim != 3 or image.shape[2] < 3:
            metadata["weak_direction_overlay_failure_reason"] = "invalid_rgb_snapshot"
            return None, metadata
        h, w = image.shape[:2]
        bottle_hull = point_list_or_none(hull_result.get("image_bottle_hull_px"))
        contact_meta = contact_patch_visualization_from_mask(hull_result, image.shape[:2], depth_snapshot)
        contact_hull = point_list_or_none(contact_meta.get("contact_hull_vertices_px")) or point_list_or_none(hull_result.get("contact_region_hull_px"))
        left_patch_poly = point_list_or_none(contact_meta.get("left_contact_patch_polygon_px"))
        right_patch_poly = point_list_or_none(contact_meta.get("right_contact_patch_polygon_px"))
        contacts = hull_result.get("contact_points_px") or {}
        center = point_or_none(contacts.get("object_center"))
        if center is None:
            center = polygon_center_from_points(bottle_hull) if bottle_hull else None
        if center is None:
            metadata["weak_direction_overlay_failure_reason"] = "missing_object_center"
            center = np.asarray([w * 0.5, h * 0.5], dtype=float)

        if bottle_hull:
            pts = np.round(np.asarray(bottle_hull, dtype=float)).astype(np.int32).reshape(-1, 1, 2)
            mask_layer = image.copy()
            cv2.fillPoly(mask_layer, [pts], (255, 225, 0), cv2.LINE_AA)
            image = cv2.addWeighted(mask_layer, 0.13, image, 0.87, 0)
            cv2.polylines(image, [pts], True, (255, 225, 0), 2, cv2.LINE_AA)
            draw_label_with_halo(image, "Bottle mask", (max(8, np.min(pts[:, 0, 0]) + 4), max(18, np.min(pts[:, 0, 1]) - 6)), 0.44, (255, 235, 70), 1)
        else:
            bbox = hull_result.get("bottle_bbox_xyxy")
            if bbox and len(bbox) >= 4:
                x1, y1, x2, y2 = [int(round(float(v))) for v in bbox[:4]]
                cv2.rectangle(image, (x1, y1), (x2, y2), (255, 225, 0), 2, cv2.LINE_AA)
                metadata["bottle_mask_source"] = metadata["bottle_mask_source"] or "bbox_fallback"

        for label, poly in (("L", left_patch_poly), ("R", right_patch_poly)):
            if poly:
                pts = np.round(np.asarray(poly, dtype=float)).astype(np.int32).reshape(-1, 1, 2)
                overlay = image.copy()
                cv2.fillPoly(overlay, [pts], (255, 0, 255), cv2.LINE_AA)
                image = cv2.addWeighted(overlay, 0.34, image, 0.66, 0)
                cv2.polylines(image, [pts], True, (255, 0, 255), 2, cv2.LINE_AA)
                centroid = polygon_center_from_points(poly)
                if centroid is not None:
                    draw_label_with_halo(image, label, (centroid[0] - 4, centroid[1] - 8), 0.38, (255, 160, 255), 1)

        if contact_hull:
            contact_pts = np.round(np.asarray(contact_hull, dtype=float)).astype(np.int32).reshape(-1, 1, 2)
            cv2.polylines(image, [contact_pts], True, (255, 255, 255), 1, cv2.LINE_AA)
            cv2.polylines(image, [contact_pts], True, (255, 0, 255), 2, cv2.LINE_AA)
            bbox = polygon_bbox_from_points(contact_hull)
            if bbox:
                label_y = min(float(h - 10), float(bbox[3]) + 17.0)
                draw_label_with_halo(image, "Contact hull", (float(bbox[0]), label_y), 0.38, (255, 120, 255), 1)

        for key, color in (("left", (255, 80, 255)), ("right", (255, 80, 255))):
            p = point_or_none(contact_meta.get(f"{key}_contact_center_px"))
            if p is None:
                p = point_or_none(contacts.get(key))
            if p is not None:
                x, y = int(round(float(p[0]))), int(round(float(p[1])))
                cv2.circle(image, (x, y), 7, (255, 255, 255), -1, cv2.LINE_AA)
                cv2.circle(image, (x, y), 5, color, -1, cv2.LINE_AA)
        for key in ("left", "right"):
            p = point_or_none(contacts.get(key))
            if p is not None:
                x, y = int(round(float(p[0]))), int(round(float(p[1])))
                cv2.circle(image, (x, y), 9, (0, 255, 255), 1, cv2.LINE_AA)

        draw_center_cross(image, center, (255, 255, 255), 10, 2)
        contact_midpoint, contact_axis, contact_normal, midpoint_source = image_quality_contact_midpoint(contact_meta, contacts)
        c = np.asarray(center, dtype=float)[:2]
        quality_c = np.asarray(contact_midpoint, dtype=float)[:2] if contact_midpoint is not None else c
        style = epsilon_visual_style(hull_result)
        epsilon_radius = float(style["epsilon_visual_radius_px"])
        epsilon_color = tuple(int(v) for v in style["epsilon_visual_color_bgr"])
        is_stale = bool(
            hull_result.get("quality_label_stale")
            or hull_result.get("matrix_stale_due_to_invalidation")
            or hull_result.get("matrix_stale_due_to_motion")
        )
        if is_stale:
            draw_dashed_circle(image, quality_c, epsilon_radius, epsilon_color, 2)
        else:
            cv2.circle(
                image,
                (int(round(quality_c[0])), int(round(quality_c[1]))),
                int(round(epsilon_radius)),
                epsilon_color,
                2,
                cv2.LINE_AA,
            )
        draw_center_cross(image, quality_c, (255, 255, 255), 5, 1)
        epsilon_label_y = max(14.0, quality_c[1] - epsilon_radius - 7.0)
        draw_label_with_halo(image, "quality radius", (quality_c[0] - 38.0, epsilon_label_y), 0.38, epsilon_color, 1)
        metadata.update({
            "contact_midpoint_px": json_safe(quality_c.tolist()),
            "contact_axis_px": None if contact_axis is None else json_safe(contact_axis.tolist()),
            "contact_normal_px": None if contact_normal is None else json_safe(contact_normal.tolist()),
            "contact_midpoint_source": midpoint_source,
            "epsilon_visual_radius_px": epsilon_radius,
            "epsilon_visual_score": style["epsilon_visual_score"],
            "epsilon_visual_quality_band": style["epsilon_visual_quality_band"],
            "epsilon_visual_mapping_source": style["epsilon_visual_mapping_source"],
            "epsilon_visual_indicator_label": "quality_radius_not_physical_pixels",
            "epsilon_visual_stale": is_stale,
        })
        # Keep the operator's primary quality close-up free of vector arrows.
        # The engineering overlay below retains the analytic weak-wrench arrow.
        operator_quality_image = image.copy()
        weak = hull_result.get("weak_direction")
        weak_missing_reason = None
        force_vec = None
        tau = None
        if weak is None:
            weak_missing_reason = "missing_weak_direction"
        else:
            try:
                weak_arr = np.asarray(weak, dtype=float).reshape(-1)
                if weak_arr.size < 3 or not np.all(np.isfinite(weak_arr[:3])):
                    weak_missing_reason = "invalid_weak_direction"
                else:
                    force_vec = weak_arr[:2]
                    tau = float(weak_arr[2])
                    metadata["weak_torque_component"] = tau
            except Exception:
                weak_missing_reason = "invalid_weak_direction"

        if force_vec is not None:
            force_norm = float(np.linalg.norm(force_vec))
            if force_norm > 1e-6:
                unit = force_vec / force_norm
                hull_scale = 70.0
                if bottle_hull:
                    bbox = polygon_bbox_from_points(bottle_hull)
                    if bbox:
                        hull_scale = max(48.0, min(95.0, 0.22 * max(float(bbox[2] - bbox[0]), float(bbox[3] - bbox[1]))))
                start = (int(round(quality_c[0])), int(round(quality_c[1])))
                end_pt = quality_c + unit * hull_scale
                end_pt[0] = np.clip(end_pt[0], 0, w - 1)
                end_pt[1] = np.clip(end_pt[1], 0, h - 1)
                end = (int(round(end_pt[0])), int(round(end_pt[1])))
                cv2.arrowedLine(image, start, end, (255, 32, 32), 3, cv2.LINE_AA, tipLength=0.22)
                draw_label_with_halo(image, "grasp weakness - not motion", (end_pt[0] + 6.0, end_pt[1] - 6.0), 0.38, (255, 64, 64), 1)
                metadata["weak_force_direction_px"] = [float(unit[0]), float(unit[1])]
                metadata["weak_direction_arrow_start_px"] = json_safe(quality_c.tolist())
                metadata["weak_direction_arrow_end_px"] = json_safe(end_pt.tolist())
            else:
                weak_missing_reason = "weak_force_component_near_zero"

        if tau is not None and abs(tau) >= 0.25:
            radius = 42
            if bottle_hull:
                bbox = polygon_bbox_from_points(bottle_hull)
                if bbox:
                    radius = int(round(max(32.0, min(70.0, 0.14 * max(float(bbox[2] - bbox[0]), float(bbox[3] - bbox[1]))))))
            center_i = (int(round(quality_c[0])), int(round(quality_c[1])))
            if tau >= 0:
                start_angle, end_angle = 210, 520
                arrow_angle = math.radians(520)
                rotation_label = "Rotation risk: clockwise"
            else:
                start_angle, end_angle = 520, 210
                arrow_angle = math.radians(210)
                rotation_label = "Rotation risk: counterclockwise"
            cv2.ellipse(image, center_i, (radius, radius), 0, start_angle, end_angle, (255, 32, 32), 2, cv2.LINE_AA)
            arrow_tip = np.asarray([quality_c[0] + radius * math.cos(arrow_angle), quality_c[1] + radius * math.sin(arrow_angle)])
            tangent = np.asarray([-math.sin(arrow_angle), math.cos(arrow_angle)])
            if tau < 0:
                tangent = -tangent
            base = arrow_tip - tangent * 13.0
            left = base + np.asarray([-tangent[1], tangent[0]]) * 5.0
            right = base - np.asarray([-tangent[1], tangent[0]]) * 5.0
            tri = np.round(np.vstack([arrow_tip, left, right])).astype(np.int32).reshape(-1, 1, 2)
            cv2.fillPoly(image, [tri], (255, 32, 32), cv2.LINE_AA)
        else:
            rotation_label = "Rotation risk: low torque component"

        epsilon_text = hull_result.get("raw_epsilon", hull_result.get("epsilon"))
        try:
            epsilon_text = f"{float(epsilon_text):.3f}"
        except Exception:
            epsilon_text = "N/A"
        labels = [
            f"Quality: {hull_result.get('quality_label', 'N/A')}",
            "Status: STALE" if is_stale else "Status: CURRENT",
            f"epsilon: {epsilon_text}",
            f"Contact source: {contact_meta.get('contact_source') or hull_result.get('contact_source') or 'N/A'}",
            "Analytic grasp weakness - NOT OBJECT MOTION",
        ]
        if weak_missing_reason:
            labels[-1] = "Analytic grasp weakness: unavailable"
            metadata["weak_direction_overlay_failure_reason"] = weak_missing_reason

        y = 22
        for text in labels:
            cv2.putText(image, text, (10, y), cv2.FONT_HERSHEY_SIMPLEX, 0.56, (0, 0, 0), 3, cv2.LINE_AA)
            cv2.putText(image, text, (10, y), cv2.FONT_HERSHEY_SIMPLEX, 0.56, (255, 255, 255), 1, cv2.LINE_AA)
            y += 22
        y = 22
        for text in labels[:4]:
            cv2.putText(operator_quality_image, text, (10, y), cv2.FONT_HERSHEY_SIMPLEX, 0.56, (0, 0, 0), 3, cv2.LINE_AA)
            cv2.putText(operator_quality_image, text, (10, y), cv2.FONT_HERSHEY_SIMPLEX, 0.56, (255, 255, 255), 1, cv2.LINE_AA)
            y += 22

        path = OUTPUT_DIR / "grasp_quality_bottle_mask_weak_direction.png"
        cv2.imwrite(str(path), cv2.cvtColor(image, cv2.COLOR_RGB2BGR), [int(cv2.IMWRITE_PNG_COMPRESSION), 3])
        metadata.update(write_quality_overlay_variants(image))
        metadata.update(write_quality_context_closeup(operator_quality_image, hull_result))
        contact_paths = save_contact_patch_debug_images(rgb_snapshot, hull_result, contact_meta, weak_image=image)
        contact_meta.update(contact_paths)
        contact_meta["contact_hull_debug_path"] = write_contact_hull_debug(contact_meta, hull_result)
        metadata.update(contact_meta)
        metadata["weak_direction_overlay_path"] = "output/grasp_quality_bottle_mask_weak_direction.png"
        metadata["weak_direction_overlay_status"] = "updated" if not weak_missing_reason else "weak_direction_unavailable"
        return str(path), metadata
    except Exception as exc:
        metadata["weak_direction_overlay_failure_reason"] = str(exc)
        return None, metadata


def debug_stream_output_enabled(name):
    global LAST_DEBUG_STREAM_STATE_READ, DEBUG_STREAM_STATE
    if name == "rgb" and STREAM_DEBUG_RGB:
        return True
    if name == "depth" and STREAM_DEBUG_DEPTH:
        return True
    now = time.monotonic()
    if now - LAST_DEBUG_STREAM_STATE_READ >= 0.25:
        LAST_DEBUG_STREAM_STATE_READ = now
        try:
            with open(DEBUG_STREAM_STATE_PATH, "r") as f:
                state = json.load(f)
            DEBUG_STREAM_STATE = {
                "rgb": bool(state.get("rgb", False)),
                "depth": bool(state.get("depth", False)),
            }
        except Exception:
            DEBUG_STREAM_STATE = {
                "rgb": bool(STREAM_DEBUG_RGB),
                "depth": bool(STREAM_DEBUG_DEPTH),
            }
    return bool(DEBUG_STREAM_STATE.get(name, False))


def debug_stream_due(name, last_time):
    if not debug_stream_output_enabled(name):
        return False, last_time
    interval = 1.0 / max(DEBUG_STREAM_FPS, 0.1)
    now = time.monotonic()
    if now - float(last_time or 0.0) >= interval:
        return True, now
    return False, last_time


def append_jsonl(path, value):
    OUTPUT_DIR.mkdir(exist_ok=True)
    with open(path, "a") as f:
        f.write(json.dumps(json_safe(value)) + "\n")


def append_target_lock_trace(value):
    """Append a bounded best-effort diagnostic trace without risking capture.

    The trace is helpful for proving lock continuity, but it is not a runtime
    control output.  A locked Windows bind-mount file therefore must never
    crash the RealSense writer.  Keep at most the active file plus one backup.
    """
    path = Path(TARGET_LOCK_TRACE_PATH)
    backup_path = path.with_name(path.name + ".previous")
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists() and path.stat().st_size >= TARGET_LOCK_TRACE_MAX_BYTES:
            if backup_path.exists():
                try:
                    backup_path.unlink()
                except OSError:
                    # Do not grow past the cap when the Windows host has the
                    # old trace open. A future append can retry rotation.
                    return False
            rotated = False
            for attempt in range(4):
                try:
                    path.replace(backup_path)
                    rotated = True
                    break
                except PermissionError:
                    if attempt < 3:
                        time.sleep(0.01 * (2 ** attempt))
                except OSError:
                    break
            if not rotated:
                return False
        with open(path, "a") as f:
            f.write(json.dumps(json_safe(value)) + "\n")
        return True
    except (OSError, TypeError, ValueError):
        return False


def make_attempt_id(frame_id):
    return f"attempt_{int(frame_id)}_{int(time.time() * 1000)}"


def epsilon_note():
    return (
        "Epsilon is a planar wrench-space closure metric computed from the selected visual contact patch centers. "
        "It supports the decision but does not directly measure force or pressure."
    )


