def segmentation_confidence_summary(pose, depth_context=None, visibility=None):
    if not pose:
        return {
            "raw_mask_confidence": 0.0,
            "cleaned_mask_confidence": 0.0,
            "body_mask_confidence": 0.0,
            "depth_support_ratio": 0.0,
            "contour_quality_score": 0.0,
            "cap_body_separation_confidence": None,
            "cap_like_end_region_status": "NOT_TESTED_POSE_MISSING",
            "cap_like_end_region_physically_validated": False,
            "crop_occlusion_warning": "pose_missing",
            "segmentation_source": "failed",
        }
    cleaned = pose.get("cleaned_mask")
    body = pose.get("body_mask") if pose.get("body_mask") is not None else cleaned
    raw = pose.get("raw_mask", cleaned)
    cleaned_area = float(np.count_nonzero(cleaned)) if cleaned is not None else 0.0
    body_area = float(np.count_nonzero(body)) if body is not None else 0.0
    raw_area = float(np.count_nonzero(raw)) if raw is not None else cleaned_area
    image_area = float(cleaned.shape[0] * cleaned.shape[1]) if cleaned is not None else 1.0
    raw_conf = float(np.clip(100.0 * raw_area / max(cleaned_area, 1.0), 0.0, 100.0)) if cleaned_area else 0.0
    cleaned_conf = float(np.clip(100.0 * cleaned_area / max(raw_area, 1.0), 0.0, 100.0)) if raw_area else 0.0
    body_conf = float(np.clip(100.0 * body_area / max(cleaned_area, 1.0), 0.0, 100.0)) if cleaned_area else 0.0
    depth = (depth_context or {}).get("depth_smooth")
    depth_support = 0.0
    if depth is not None and body is not None and body_area > 0:
        depth_support = float(np.count_nonzero((body > 0) & valid_depth_mask(depth)) / max(body_area, 1.0))
    contour = pose.get("body_contour") if pose.get("body_contour") is not None else pose.get("contour")
    contour_quality = 0.0
    if contour is not None and body_area > 0:
        try:
            contour_cv = np.asarray(contour, dtype=np.float32)
            if contour_cv.size >= 6 and contour_cv.size % 2 == 0:
                contour_cv = contour_cv.reshape(-1, 2)
                contour_cv = contour_cv[np.all(np.isfinite(contour_cv), axis=1)]
                if contour_cv.shape[0] >= 3:
                    perimeter = max(
                        float(cv2.arcLength(contour_cv.reshape(-1, 1, 2), True)),
                        1.0,
                    )
                    compactness = 4.0 * np.pi * body_area / (perimeter * perimeter)
                    contour_quality = float(np.clip(compactness * 160.0, 0.0, 100.0))
        except (TypeError, ValueError, cv2.error):
            # Contour quality is diagnostic only. A serialized or malformed
            # contour must remain unscored instead of aborting RGB-D tracking.
            contour_quality = 0.0
    crop_warning = None
    if visibility and not visibility.get("full_bottle_visible", True):
        crop_warning = "full_bottle_cropped"
    cap_evidence = pose.get("cap_like_end_region") or {}
    cap_confidence = first_number(cap_evidence.get("confidence"))
    if cap_evidence.get("detected") is not True:
        cap_confidence = None
    return {
        "raw_mask_confidence": raw_conf,
        "cleaned_mask_confidence": cleaned_conf,
        "body_mask_confidence": body_conf,
        "depth_support_ratio": depth_support,
        "contour_quality_score": contour_quality,
        "cap_body_separation_confidence": (
            float(np.clip(100.0 * cap_confidence, 0.0, 100.0))
            if cap_confidence is not None
            else None
        ),
        "cap_like_end_region_status": cap_evidence.get(
            "status", "NOT_TESTED_NO_CAP_LIKE_ESTIMATOR_EVIDENCE"
        ),
        "cap_like_end_region_physically_validated": False,
        "crop_occlusion_warning": crop_warning,
        "segmentation_source": pose.get("segmentation_source", "OpenCV-depth"),
    }


def get_yolo_detector():
    global YOLO_DETECTOR, YoloBottleDetector, expand_bbox_xyxy
    if not USE_YOLO_BOTTLE_TRIGGER:
        raise RuntimeError("YOLO trigger is disabled for the final fast demo path.")
    if YoloBottleDetector is None or expand_bbox_xyxy is None:
        from yolo_bottle_detector import YoloBottleDetector as _YoloBottleDetector, expand_bbox_xyxy as _expand_bbox_xyxy

        YoloBottleDetector = _YoloBottleDetector
        expand_bbox_xyxy = _expand_bbox_xyxy
    if YOLO_DETECTOR is None:
        YOLO_DETECTOR = YoloBottleDetector(
            model_path=YOLO_MODEL_PATH,
            conf_threshold=YOLO_CONF_THRESHOLD,
        )
    return YOLO_DETECTOR


