def _scale_points(points, sx, sy):
    if points is None:
        return None
    arr = np.asarray(points, dtype=float).copy()
    if arr.size == 0:
        return points
    arr[..., 0] *= sx
    arr[..., 1] *= sy
    return arr


def _resize_mask_to_shape(mask, image_shape):
    if mask is None:
        return None
    h, w = image_shape[:2]
    return cv2.resize(mask.astype(np.uint8), (w, h), interpolation=cv2.INTER_NEAREST)


def scale_cap_like_evidence(evidence, sx, sy, axis_vector=None, coordinate_frame="full_image_pixels"):
    if not isinstance(evidence, dict):
        return evidence
    scaled = copy.deepcopy(evidence)
    axis = np.asarray(axis_vector if axis_vector is not None else [0.0, 1.0], dtype=float).reshape(-1)[:2]
    if axis.size != 2 or not np.all(np.isfinite(axis)) or float(np.linalg.norm(axis)) <= 1e-9:
        axis = np.array([0.0, 1.0], dtype=float)
    axis = axis / max(float(np.linalg.norm(axis)), 1e-9)
    width_axis = np.array([-axis[1], axis[0]], dtype=float)
    axial_scale = float(np.linalg.norm(axis * np.array([sx, sy], dtype=float)))
    lateral_scale = float(np.linalg.norm(width_axis * np.array([sx, sy], dtype=float)))
    for key, factor in (
        ("axial_span_px", axial_scale),
        ("lateral_span_px", lateral_scale),
    ):
        value = first_number(scaled.get(key))
        if value is not None:
            scaled[key] = float(value * factor)
    for key in (
        "added_pixel_count",
        "minimum_area_px",
        "hand_skin_excluded_pixel_count",
    ):
        area_value = first_number(scaled.get(key))
        if area_value is not None:
            scaled[key] = int(round(area_value * float(sx) * float(sy)))
    search_roi = scaled.get("search_roi_xyxy")
    if isinstance(search_roi, (list, tuple)) and len(search_roi) >= 4:
        scaled["search_roi_xyxy"] = [
            float(search_roi[0]) * float(sx),
            float(search_roi[1]) * float(sy),
            float(search_roi[2]) * float(sx),
            float(search_roi[3]) * float(sy),
        ]
    estimated_extent = scaled.get("estimated_whole_extent_bbox_xywh")
    if isinstance(estimated_extent, (list, tuple)) and len(estimated_extent) >= 4:
        scaled["estimated_whole_extent_bbox_xywh"] = [
            float(estimated_extent[0]) * float(sx),
            float(estimated_extent[1]) * float(sy),
            float(estimated_extent[2]) * float(sx),
            float(estimated_extent[3]) * float(sy),
        ]
    scaled["source_coordinate_frame"] = evidence.get("coordinate_frame", "detector_input_pixels")
    scaled["coordinate_frame"] = coordinate_frame
    scaled["coordinate_scale_xy"] = [float(sx), float(sy)]
    return scaled


def scale_pose_to_full(pose, full_shape, scaled_shape):
    if pose is None:
        return None
    full_h, full_w = full_shape[:2]
    scaled_h, scaled_w = scaled_shape[:2]
    sx = float(full_w) / max(float(scaled_w), 1.0)
    sy = float(full_h) / max(float(scaled_h), 1.0)
    out = dict(pose)
    if pose.get("bbox_xywh"):
        x, y, bw, bh = pose["bbox_xywh"]
        out["bbox_xywh"] = [int(round(x * sx)), int(round(y * sy)), int(round(bw * sx)), int(round(bh * sy))]
    for key in ("center_px",):
        if pose.get(key) is not None:
            out[key] = [float(pose[key][0]) * sx, float(pose[key][1]) * sy]
    axis = point_or_none(pose.get("axis_vector"))
    if axis is not None:
        scaled_axis = np.array([float(axis[0]) * sx, float(axis[1]) * sy], dtype=float)
        axis_scale = float(np.linalg.norm(scaled_axis))
        if axis_scale > 1e-9:
            out["axis_vector"] = (scaled_axis / axis_scale).tolist()
            out["axis_angle_degrees"] = float(np.degrees(np.arctan2(out["axis_vector"][1], out["axis_vector"][0])))
            if pose.get("axis_length_px") is not None:
                out["axis_length_px"] = float(pose["axis_length_px"]) * axis_scale
    for key in ("oriented_bbox",):
        if pose.get(key) is not None:
            out[key] = _scale_points(pose[key], sx, sy).astype(int).tolist()
    for key in ("contour", "body_contour"):
        if pose.get(key) is not None:
            out[key] = _scale_points(pose[key], sx, sy).astype(np.int32)
    for key in ("mask", "raw_mask", "cleaned_mask", "body_mask", "cap_like_mask"):
        if pose.get(key) is not None:
            out[key] = _resize_mask_to_shape(pose[key], full_shape)
    scaled_cap_evidence = scale_cap_like_evidence(
        pose.get("cap_like_end_region"),
        sx,
        sy,
        pose.get("axis_vector"),
        coordinate_frame="full_image_pixels",
    )
    if scaled_cap_evidence is not None:
        out["cap_like_end_region"] = scaled_cap_evidence
    if pose.get("area_ratio") is not None:
        out["area_ratio"] = float(np.count_nonzero(out.get("cleaned_mask", 0)) / max(float(full_h * full_w), 1.0))
    breakdown = dict(pose.get("candidate_score_breakdown") or {})
    if scaled_cap_evidence is not None:
        breakdown["cap_like_end_region"] = copy.deepcopy(scaled_cap_evidence)
    breakdown["prelock_detection_scale"] = PRELOCK_DETECTION_SCALE
    breakdown["scaled_to_full_frame"] = True
    out["candidate_score_breakdown"] = breakdown
    out["detection_source"] = f"{pose.get('detection_source', 'opencv_depth_fallback')}_scaled_{PRELOCK_DETECTION_SCALE:g}"
    out["segmentation_source"] = f"{pose.get('segmentation_source', 'unknown')}_scaled_{PRELOCK_DETECTION_SCALE:g}"
    return out


def detect_bottle_pose_scaled(rgb, depth, scale=PRELOCK_DETECTION_SCALE, intrinsics=None):
    scale = float(scale or 1.0)
    if scale >= 0.98:
        return detect_bottle_pose(rgb, depth, intrinsics=intrinsics)
    h, w = rgb.shape[:2]
    sw = max(80, int(round(w * scale)))
    sh = max(60, int(round(h * scale)))
    small_rgb = cv2.resize(rgb, (sw, sh), interpolation=cv2.INTER_AREA)
    small_depth = cv2.resize(depth, (sw, sh), interpolation=cv2.INTER_NEAREST)
    small_intrinsics = {
        **(intrinsics or {}),
        **{
            key: float((intrinsics or {}).get(key)) * scale
            for key in ("fx", "fy", "cx", "cy")
            if (intrinsics or {}).get(key) is not None
        },
    }
    pose, error = detect_bottle_pose(small_rgb, small_depth, intrinsics=small_intrinsics)
    if pose is None:
        return None, error
    return scale_pose_to_full(pose, rgb.shape, small_rgb.shape), error


def detect_bottle_poses_scaled(rgb, depth, scale=PRELOCK_DETECTION_SCALE, intrinsics=None):
    scale = float(scale or 1.0)
    if scale >= 0.98:
        return detect_bottle_poses(rgb, depth, intrinsics=intrinsics)
    h, w = rgb.shape[:2]
    sw = max(80, int(round(w * scale)))
    sh = max(60, int(round(h * scale)))
    small_rgb = cv2.resize(rgb, (sw, sh), interpolation=cv2.INTER_AREA)
    small_depth = cv2.resize(depth, (sw, sh), interpolation=cv2.INTER_NEAREST)
    small_intrinsics = {
        **(intrinsics or {}),
        **{
            key: float((intrinsics or {}).get(key)) * scale
            for key in ("fx", "fy", "cx", "cy")
            if (intrinsics or {}).get(key) is not None
        },
    }
    poses, error = detect_bottle_poses(small_rgb, small_depth, intrinsics=small_intrinsics)
    return [scale_pose_to_full(pose, rgb.shape, small_rgb.shape) for pose in poses], error


def detect_prelock_rgbd_poses(rgb, depth, intrinsics=None, *, force_full_resolution=False):
    """Use the existing scaled detector for the high-rate demo search path."""
    if (
        not force_full_resolution
        and SINGLE_BOTTLE_DEMO_MODE
        and FAST_FINAL_DEMO_MODE
        and PRELOCK_FAST_SCALED_RGBD
    ):
        poses, error = detect_bottle_poses_scaled(
            rgb,
            depth,
            PRELOCK_DETECTION_SCALE,
            intrinsics=intrinsics,
        )
        return poses, error, "scaled"
    poses, error = detect_bottle_poses(rgb, depth, intrinsics=intrinsics)
    return poses, error, (
        "full_resolution_lock_confirmation"
        if force_full_resolution
        else "full_resolution"
    )


def prelock_full_resolution_confirmation_due(lock_manager):
    """Latch full-resolution confirmation after scaled search finds a target."""
    if lock_manager is None or not getattr(lock_manager, "enabled", False):
        return False
    if getattr(lock_manager, "prelock_full_confirmation_active", False):
        return True
    required = (
        int(lock_manager.relock_required_frames)
        if getattr(lock_manager, "has_lost_lock", False)
        else int(TARGET_LOCK_STABLE_FRAMES)
    )
    return int(getattr(lock_manager, "stable_full_bottle_frames", 0) or 0) >= max(0, required - 1)


def prelock_pose_detection_resolution(pose):
    """Classify current acquisition evidence without trusting source strings."""
    pose = pose or {}
    explicit = str(pose.get("prelock_detection_resolution") or "").lower()
    if explicit:
        return "scaled" if explicit == "scaled" else "full_resolution"
    breakdown = pose.get("candidate_score_breakdown") or {}
    return (
        "scaled"
        if breakdown.get("scaled_to_full_frame") is True
        else "full_resolution"
    )


def match_locked_bottle_pose(poses, lock_manager, image_shape):
    """Choose the detection nearest the last locked geometry without retargeting."""
    if not poses:
        return None
    active_locked = getattr(lock_manager, "locked_target", None)
    last_lost = getattr(lock_manager, "last_lost_target", None)
    locked = active_locked or last_lost or {}
    matching_after_loss = bool(not active_locked and last_lost)
    live_last_verified = getattr(lock_manager, "last_good_bottle_geometry", None)
    persisted_last_verified = locked.get("last_verified_bottle_geometry") or {}
    full_anchor = (
        locked.get("full_bottle_anchor_geometry")
        or locked.get("locked_bottle_geometry")
        or {}
    )
    reference = (
        live_last_verified
        or persisted_last_verified
        or full_anchor
    )
    reference_source = (
        "live_last_verified_rgbd_geometry"
        if live_last_verified
        else "persisted_last_verified_rgbd_geometry_not_current"
        if persisted_last_verified
        else "full_bottle_lock_anchor"
        if full_anchor
        else "original_lock_geometry"
    )
    center = point_or_none(reference.get("center_px"))
    if center is None:
        center = bbox_center_xy(geometry_bbox_xyxy(reference))
    if center is None:
        return None
    diagonal = max(float(np.hypot(image_shape[1], image_shape[0])), 1.0)
    reference_depth = first_number(reference.get("depth_median_mm"), locked.get("depth_mm_at_lock"))
    reference_bbox = geometry_bbox_xyxy(reference)
    reference_axis = point_or_none(reference.get("axis_vector"))
    reference_aspect, reference_aspect_source = geometry_long_short_aspect(reference, reference_bbox)
    max_center_distance = max(36.0, 0.12 * diagonal)

    def match_candidate(pose):
        pose_center = point_or_none(pose.get("center_px"))
        if pose_center is None:
            return None
        center_distance = float(np.linalg.norm(pose_center - center))
        pose_bbox = geometry_bbox_xyxy(pose)
        pose_depth = first_number(pose.get("depth_median_mm"))
        comparison_bbox = reference_bbox
        projection = {
            "roi_depth_projection_scale": 1.0,
            "roi_projected_bbox_unclipped": json_safe(reference_bbox),
            "roi_projected_visible_fraction": 1.0,
            "roi_projected_extent_partial": False,
            "roi_projected_boundary_touches": {
                "left": False,
                "top": False,
                "right": False,
                "bottom": False,
            },
        }
        if reference_bbox and reference_depth and pose_depth:
            comparison_bbox, projection = project_bbox_for_depth(
                reference_bbox,
                reference_depth,
                pose_depth,
                image_shape,
            )
            comparison_bbox = comparison_bbox or reference_bbox
        overlap = bbox_iou_xyxy(comparison_bbox, pose_bbox) if comparison_bbox and pose_bbox else 0.0
        if reference_bbox and pose_bbox and overlap < 0.05:
            return None
        if center_distance > max_center_distance and overlap < 0.05:
            return None
        depth_ratio = 0.0
        if reference_depth and pose_depth:
            depth_ratio = abs(float(pose_depth) - float(reference_depth)) / max(float(reference_depth), 1.0)
            if depth_ratio > 0.58:
                return None
        size_cost = 0.0
        if comparison_bbox and pose_bbox:
            expected_area = bbox_area_px(comparison_bbox)
            pose_area = bbox_area_px(pose_bbox)
            if expected_area > 0.0 and pose_area > 0.0:
                area_ratio = pose_area / expected_area
                if reference_depth and pose_depth and (area_ratio < 0.25 or area_ratio > 4.0):
                    return None
                size_cost = abs(float(np.log(max(area_ratio, 1e-6))))
        pose_aspect, pose_aspect_source = geometry_long_short_aspect(pose, pose_bbox)
        aspect_cost = 0.0
        if reference_aspect is not None and pose_aspect is not None:
            aspect_delta = max(reference_aspect, pose_aspect) / max(min(reference_aspect, pose_aspect), 1e-6)
            both_rotation_invariant = bool(
                reference_aspect_source == "oriented_bbox_rotation_invariant"
                and pose_aspect_source == "oriented_bbox_rotation_invariant"
            )
            if both_rotation_invariant and aspect_delta > POST_LOCK_ROI_MAX_ASPECT_RATIO_DELTA:
                return None
            aspect_cost = abs(float(np.log(max(aspect_delta, 1.0))))
        pose_axis = point_or_none(pose.get("axis_vector"))
        axis_cost = 0.0
        if reference_axis is not None and pose_axis is not None:
            reference_norm = reference_axis / max(float(np.linalg.norm(reference_axis)), 1e-9)
            pose_norm = pose_axis / max(float(np.linalg.norm(pose_axis)), 1e-9)
            alignment = abs(float(np.dot(reference_norm, pose_norm)))
            if alignment < float(np.cos(np.deg2rad(40.0))):
                return None
            axis_cost = 1.0 - alignment
        center_cost = center_distance / diagonal
        score = center_cost + 0.20 * depth_ratio + 0.08 * axis_cost + 0.04 * size_cost + 0.03 * aspect_cost - 0.08 * overlap
        return score, projection, comparison_bbox

    matches = []
    for pose in poses:
        result = match_candidate(pose)
        if result is not None:
            score, projection, comparison_bbox = result
            matches.append((score, pose, projection, comparison_bbox))
    matches.sort(key=lambda item: item[0])
    if not matches:
        return None
    if len(matches) > 1 and matches[1][0] - matches[0][0] < 0.025:
        return None
    matched_pose = matches[0][1]
    matched_projection = matches[0][2]
    matched_comparison_bbox = matches[0][3]
    matched_pose["full_extent_reference_source"] = reference_source
    matched_pose["full_extent_reference_bbox_xyxy"] = json_safe(
        matched_comparison_bbox
    )
    matched_pose["full_extent_reference_iou"] = float(
        bbox_iou_xyxy(matched_comparison_bbox, geometry_bbox_xyxy(matched_pose))
    )
    matched_pose["projected_visible_fraction"] = matched_projection.get(
        "roi_projected_visible_fraction"
    )
    matched_pose["projected_full_extent_bbox_unclipped"] = matched_projection.get(
        "roi_projected_bbox_unclipped"
    )
    matched_pose["projected_full_extent_boundary_touches"] = matched_projection.get(
        "roi_projected_boundary_touches"
    )
    if matched_projection.get("roi_projected_extent_partial") is True:
        matched_pose["partial_extent"] = True
        matched_pose["partial_extent_reason"] = (
            "immutable_full_anchor_projects_outside_current_frame"
        )
    if matching_after_loss:
        matched_pose["identity_match_status"] = (
            "ESTIMATED_GEOMETRIC_MATCH_TO_LAST_VERIFIED_RGBD_REFERENCE"
            if reference_source == "persisted_last_verified_rgbd_geometry_not_current"
            else "ESTIMATED_GEOMETRIC_MATCH_TO_ORIGINAL_LOCK_REFERENCE"
        )
        matched_pose["identity_reference_measurement_status"] = (
            "LAST_VERIFIED_NOT_CURRENT"
            if reference_source == "persisted_last_verified_rgbd_geometry_not_current"
            else "ORIGINAL_LOCK_SNAPSHOT_NOT_CURRENT"
        )
        matched_pose["identity_reference_source"] = reference_source
        matched_pose["identity_reference_frame_id"] = locked.get("last_verified_bottle_frame_id")
        matched_pose["identity_match_physically_validated"] = False
    return matched_pose


def single_bottle_reacquisition_compatibility(pose, lock_manager, image_shape):
    """Check non-positional evidence against the active or last demo lock."""
    lost = (
        getattr(lock_manager, "locked_target", None)
        or getattr(lock_manager, "last_lost_target", None)
        or {}
    )
    reference = (
        lost.get("last_verified_bottle_geometry")
        or lost.get("full_bottle_anchor_geometry")
        or lost.get("locked_bottle_geometry")
        or {}
    )
    reasons = []
    reference_bbox = geometry_bbox_xyxy(reference)
    pose_bbox = geometry_bbox_xyxy(pose)
    reference_depth = first_number(
        reference.get("depth_median_mm"),
        lost.get("last_verified_bottle_depth_mm"),
        lost.get("depth_mm_at_lock"),
    )
    pose_depth = first_number((pose or {}).get("depth_median_mm"))
    if reference_bbox is None or pose_bbox is None:
        reasons.append("bottle_extent_unavailable")
    if reference_depth is None or pose_depth is None:
        reasons.append("depth_unavailable")
    elif abs(float(pose_depth) - float(reference_depth)) / max(float(reference_depth), 1.0) > 0.58:
        reasons.append("depth_incompatible_with_last_verified_bottle")
    if reference_bbox is not None and pose_bbox is not None and reference_depth and pose_depth:
        expected_bbox, _projection = project_bbox_for_depth(
            reference_bbox,
            reference_depth,
            pose_depth,
            image_shape,
        )
        expected_area = bbox_area_px(expected_bbox or reference_bbox)
        current_area = bbox_area_px(pose_bbox)
        if expected_area <= 0.0 or current_area <= 0.0:
            reasons.append("bottle_extent_area_invalid")
        else:
            area_ratio = current_area / expected_area
            if area_ratio < 0.25 or area_ratio > 4.0:
                reasons.append("projected_bottle_scale_incompatible")
    reference_aspect, reference_aspect_source = geometry_long_short_aspect(
        reference,
        reference_bbox,
    )
    pose_aspect, pose_aspect_source = geometry_long_short_aspect(pose, pose_bbox)
    if reference_aspect is not None and pose_aspect is not None:
        aspect_delta = max(reference_aspect, pose_aspect) / max(
            min(reference_aspect, pose_aspect),
            1e-6,
        )
        if (
            reference_aspect_source == "oriented_bbox_rotation_invariant"
            and pose_aspect_source == "oriented_bbox_rotation_invariant"
            and aspect_delta > POST_LOCK_ROI_MAX_ASPECT_RATIO_DELTA
        ):
            reasons.append("bottle_aspect_incompatible")
    reference_axis = point_or_none(reference.get("axis_vector"))
    pose_axis = point_or_none((pose or {}).get("axis_vector"))
    if reference_axis is not None and pose_axis is not None:
        reference_axis /= max(float(np.linalg.norm(reference_axis)), 1e-9)
        pose_axis /= max(float(np.linalg.norm(pose_axis)), 1e-9)
        if abs(float(np.dot(reference_axis, pose_axis))) < float(np.cos(np.deg2rad(40.0))):
            reasons.append("bottle_axis_incompatible")
    if float((pose or {}).get("detection_confidence", 0.0) or 0.0) < 0.45:
        reasons.append("detection_confidence_too_low")
    if float((pose or {}).get("depth_confidence", 0.0) or 0.0) < 0.60:
        reasons.append("depth_confidence_too_low")
    return not reasons, reasons


def demo_bottle_identity_eligibility(pose):
    """Return the strict current known-blue identity contract for the demo."""
    pose = pose or {}
    reasons = []
    if pose.get("measurement_status") != "CURRENT_MEASURED_RGBD":
        reasons.append("demo_identity_requires_current_measured_rgbd")
    if str(pose.get("bottle_detection_status") or "").upper() != "CANDIDATE":
        reasons.append("demo_identity_detection_status_not_candidate")
    if float(pose.get("detection_confidence", 0.0) or 0.0) < 0.45:
        reasons.append("demo_identity_detection_confidence_too_low")
    if float(pose.get("depth_confidence", 0.0) or 0.0) < 0.60:
        reasons.append("demo_identity_depth_confidence_too_low")
    if pose.get("bottle_profile_valid") is not True:
        reasons.append("demo_identity_bottle_profile_invalid")
    if pose.get("segmentation_rejection_reasons"):
        reasons.append("demo_identity_segmentation_rejected")
    if not str(pose.get("segmentation_source") or "").lower().startswith("rgb"):
        reasons.append("demo_identity_requires_known_blue_rgb_component")
    if float(pose.get("bottle_color_fraction", 0.0) or 0.0) < 0.55:
        reasons.append("demo_identity_known_blue_support_too_low")
    return not reasons, reasons


def annotate_demo_depth_foreground_override(pose):
    """Allow one narrowly evidenced mixed-edge depth case for the known bottle.

    The D405 may fill most boundary pixels of a dark curved bottle with the
    bottle depth.  The ordinary ring median must remain visible and unchanged;
    this annotation only lets the task selector use a separately measured,
    materially supported farther-background portion when all strict known-blue
    identity evidence is already current.
    """
    pose = pose or {}
    depth_geometry = pose.get("depth_geometry_evidence") or {}
    minimum_far_pixels = int(
        depth_geometry.get("depth_far_background_min_required_pixel_count", 32)
        or 32
    )
    eligible = bool(
        pose.get("prelock_full_resolution_temporally_confirmed") is True
        and depth_geometry.get("depth_foreground_separated") is False
        and depth_geometry.get("depth_mixed_boundary_foreground_supported") is True
        and float(depth_geometry.get("depth_surface_coherence_score", 0.0) or 0.0)
        >= 0.85
        and float(
            depth_geometry.get("depth_surface_interdecile_range_mm", 0.0) or 0.0
        )
        >= 6.0
        and float(
            depth_geometry.get("depth_far_background_support_fraction", 0.0) or 0.0
        )
        >= 0.08
        and int(depth_geometry.get("depth_far_background_support_pixel_count", 0) or 0)
        >= minimum_far_pixels
        and float(
            depth_geometry.get("depth_far_background_separation_mm", 0.0) or 0.0
        )
        >= 40.0
        and depth_geometry.get("depth_far_background_distributed") is True
        and int(
            depth_geometry.get("depth_far_background_supported_sector_count", 0)
            or 0
        )
        >= 2
        and int(
            depth_geometry.get("depth_far_background_opposite_sector_pair_count", 0)
            or 0
        )
        >= 1
        and float(pose.get("detection_confidence", 0.0) or 0.0) >= 0.75
        and float(pose.get("depth_confidence", 0.0) or 0.0) >= 0.90
        and float(pose.get("bottle_profile_agreement_score", 0.0) or 0.0) >= 0.65
        and float(pose.get("bottle_color_fraction", 0.0) or 0.0) >= 0.55
        and pose.get("bottle_profile_valid") is True
        and not pose.get("segmentation_rejection_reasons")
        and str(pose.get("segmentation_source") or "").lower().startswith("rgb")
    )
    pose["demo_depth_foreground_override_eligible"] = eligible
    pose["demo_depth_foreground_override_reason"] = (
        "KNOWN_BLUE_PROFILE_WITH_COHERENT_MIXED_DEPTH_BOUNDARY"
        if eligible
        else "FULL_RESOLUTION_TEMPORAL_CONFIRMATION_REQUIRED"
        if (
            depth_geometry.get("depth_mixed_boundary_foreground_supported") is True
            and pose.get("prelock_full_resolution_temporally_confirmed") is not True
        )
        else "MIXED_DEPTH_BOUNDARY_OVERRIDE_NOT_SUPPORTED"
    )
    return eligible


def select_active_locked_bottle_recovery_candidate(poses, lock_manager, image_shape):
    """Recover an active lock only through positional identity continuity.

    Single-bottle shape/depth compatibility is deliberately excluded here. It
    may start a new attempt after a true lost-lock transition, but it cannot
    relabel a remote component as the active bottle or overwrite its anchors.
    """
    eligible = []
    rejected = []
    for pose in poses or []:
        if SINGLE_BOTTLE_DEMO_MODE:
            _eligible, reasons = demo_bottle_identity_eligibility(pose)
        else:
            reasons = []
            if pose.get("measurement_status") != "CURRENT_MEASURED_RGBD":
                reasons.append("active_recovery_requires_current_measured_rgbd")
            if float(pose.get("detection_confidence", 0.0) or 0.0) < 0.45:
                reasons.append("active_recovery_detection_confidence_too_low")
            if float(pose.get("depth_confidence", 0.0) or 0.0) < 0.60:
                reasons.append("active_recovery_depth_confidence_too_low")
        if reasons:
            rejected.append({
                "target_id": pose.get("target_id"),
                "reasons": reasons,
            })
            continue
        eligible.append(pose)
    if lock_manager is not None:
        lock_manager.last_active_recovery_candidate_rejections = rejected
    return match_locked_bottle_pose(eligible, lock_manager, image_shape)


def select_lost_target_reacquisition_candidate(
    poses,
    lock_manager,
    image_shape,
    *,
    single_bottle_demo_mode=None,
):
    """Choose an honest post-loss candidate without a manual reset.

    A geometric match retains the original identity semantics.  In the
    explicitly configured single-bottle demo, one current RGB-D candidate may
    instead begin a *new* lock attempt after the existing stable-frame and
    geometry gates.  It is never described as a verified identity match.
    """
    enabled = SINGLE_BOTTLE_DEMO_MODE if single_bottle_demo_mode is None else bool(single_bottle_demo_mode)
    if enabled and len(poses or []) != 1:
        return None, "SINGLE_BOTTLE_AUTO_REACQUIRE_REQUIRES_EXACTLY_ONE_CANDIDATE"
    if enabled:
        candidate = (poses or [None])[0]
        eligible, reasons = demo_bottle_identity_eligibility(candidate)
        if not eligible:
            if lock_manager is not None:
                lock_manager.last_lost_recovery_candidate_rejections = [{
                    "target_id": (candidate or {}).get("target_id"),
                    "reasons": reasons,
                }]
            return None, "SINGLE_BOTTLE_AUTO_REACQUIRE_REQUIRES_KNOWN_BLUE_CURRENT_RGBD"
    matched = match_locked_bottle_pose(poses, lock_manager, image_shape)
    if matched is not None:
        matched["reacquired_original_target_identity"] = True
        matched["single_bottle_demo_reacquisition_candidate"] = False
        return matched, "ORIGINAL_TARGET_UNAMBIGUOUS_MATCH"
    if not enabled:
        return None, "ORIGINAL_TARGET_NOT_MATCHED"
    candidate = poses[0]
    if candidate.get("measurement_status") != "CURRENT_MEASURED_RGBD":
        return None, "SINGLE_BOTTLE_AUTO_REACQUIRE_REQUIRES_CURRENT_RGBD"
    compatible, compatibility_reasons = single_bottle_reacquisition_compatibility(
        candidate,
        lock_manager,
        image_shape,
    )
    candidate["single_bottle_reacquisition_compatibility_reasons"] = compatibility_reasons
    if not compatible:
        return None, "SINGLE_BOTTLE_AUTO_REACQUIRE_INCOMPATIBLE_CURRENT_RGBD"
    candidate["target_id"] = (
        f"single_bottle_demo_reacquired_{int(getattr(lock_manager, 'lock_generation', 0) or 0) + 1:02d}"
    )
    candidate["target_id_scope"] = "SINGLE_BOTTLE_DEMO_NEW_LOCK_CANDIDATE"
    candidate["reacquired_original_target_identity"] = False
    candidate["single_bottle_demo_reacquisition_candidate"] = True
    candidate["identity_match_status"] = "UNVERIFIED_SINGLE_CURRENT_BOTTLE_NEW_LOCK_CANDIDATE"
    candidate["identity_reference_measurement_status"] = "NOT_USED_NEW_LOCK_REQUIRED"
    candidate["identity_match_physically_validated"] = False
    candidate["auto_reacquisition_preserves_body_fraction"] = True
    return candidate, "SINGLE_BOTTLE_AUTO_REACQUIRE_STABILITY_PENDING"


def select_central_near_single_bottle_candidate(poses, image_shape):
    """Ignore distant screen/reflection duplicates when one real bottle dominates.

    The hand-mounted demo points the optical axis at the physical bottle. A TV
    behind the workspace can display the same bottle and create additional valid
    RGB-D bottle-like components. Select one candidate only when it is the sole
    center-zone object and is substantially nearer than every competing
    component; otherwise keep the ambiguous-scene fail-closed behavior.
    """
    if len(poses or []) < 2:
        return None
    height, width = image_shape[:2]
    central = []
    for pose in poses:
        center = point_or_none((pose or {}).get("center_px"))
        depth_mm = first_number((pose or {}).get("depth_median_mm"))
        if center is None or depth_mm is None:
            continue
        if (
            abs(float(center[0]) - 0.5 * float(width)) <= 0.18 * float(width)
            and abs(float(center[1]) - 0.5 * float(height)) <= 0.40 * float(height)
            and float((pose or {}).get("detection_confidence", 0.0) or 0.0) >= 0.45
            and float((pose or {}).get("depth_confidence", 0.0) or 0.0) >= 0.60
        ):
            central.append(pose)
    if len(central) != 1:
        return None
    selected = central[0]
    selected_depth = first_number(selected.get("depth_median_mm"))
    competing_depths = [
        depth_mm
        for pose in poses
        if pose is not selected
        for depth_mm in [first_number((pose or {}).get("depth_median_mm"))]
        if depth_mm is not None
    ]
    if selected_depth is None or not competing_depths:
        return None
    nearest_competitor = min(competing_depths)
    required_separation_mm = max(100.0, 0.20 * float(selected_depth))
    if float(nearest_competitor) - float(selected_depth) < required_separation_mm:
        return None
    selected["single_bottle_central_near_selection"] = True
    selected["single_bottle_central_near_depth_separation_mm"] = float(
        nearest_competitor - selected_depth
    )
    selected["single_bottle_central_near_selection_reason"] = (
        "sole_optical_axis_candidate_substantially_nearer_than_screen_or_reflection_duplicates"
    )
    return selected


def blocked_reacquisition_observation_selection(poses):
    """Report current bottles without treating any as the lost locked target."""
    candidates = []
    for index, pose in enumerate(poses or []):
        bbox_xywh = pose.get("bbox_xywh")
        if bbox_xywh is None:
            bbox_xywh = bbox_xyxy_to_xywh(geometry_bbox_xyxy(pose))
        candidates.append({
            "target_id": str(pose.get("target_id") or f"observed_bottle_{index + 1:02d}"),
            "rank": index + 1,
            "selected": False,
            "eligible": False,
            "feasibility_score": 0.0,
            "detection_confidence": float(pose.get("detection_confidence", 0.0) or 0.0),
            "bbox_xywh": json_safe(bbox_xywh),
            "center_px": json_safe(pose.get("center_px")),
            "depth_median_mm": first_number(pose.get("depth_median_mm")),
            "orientation": "UNVERIFIED_AFTER_TARGET_LOSS",
            "available_for_pickup": False,
            "occluded": False,
            "strategy": "DO_NOT_ATTEMPT",
            "approach": "BLOCKED",
            "reasons": ["original_target_identity_not_unambiguously_reacquired"],
            "evidence_status": "CURRENT_RGBD_OBSERVATION_IDENTITY_UNVERIFIED",
            "physically_validated": False,
        })
    return {
        "selected_target_id": None,
        "selection_status": "CURRENT_BOTTLES_OBSERVED_REACQUISITION_BLOCKED",
        "candidate_count": len(candidates),
        "eligible_count": 0,
        "candidates": candidates,
        "grasp_feasibility_score": 0.0,
        "grasp_feasibility_label": "HOLD_AND_ADJUST",
        "grasp_feasibility_reason": "original_target_identity_not_unambiguously_reacquired",
        "suggested_operator_action": (
            "Keep exactly one bottle clearly visible; automatic re-acquisition is waiting for a stable, unambiguous RGB-D target."
            if SINGLE_BOTTLE_DEMO_MODE
            else "Isolate the original bottle, or reset the target lock to deliberately search all current bottles."
        ),
        "suggested_robot_action": "HOLD_NO_ACTUATION",
        "limitations": [
            "CURRENT_BOTTLES_ARE_OBSERVED_BUT_NOT_IDENTIFIED_AS_THE_ORIGINAL_TARGET",
            "AUTOMATIC_NEIGHBORING_BOTTLE_RETARGETING_BLOCKED",
            *(
                ["SINGLE_BOTTLE_AUTO_REACQUISITION_REQUIRES_EXACTLY_ONE_STABLE_CURRENT_RGBD_CANDIDATE"]
                if SINGLE_BOTTLE_DEMO_MODE
                else []
            ),
        ],
        "physically_validated": False,
    }


def blocked_single_bottle_demo_selection(poses):
    """Describe multiple current bottles without silently choosing one."""
    selection = blocked_reacquisition_observation_selection(poses)
    selection.update({
        "selection_status": "SINGLE_BOTTLE_DEMO_BLOCKED_MULTIPLE_OR_AMBIGUOUS",
        "grasp_feasibility_reason": "single_bottle_demo_requires_exactly_one_current_rgbd_candidate",
        "suggested_operator_action": "Keep one bottle in view; automatic locking resumes when the target is unambiguous.",
    })
    for candidate in selection["candidates"]:
        candidate["reasons"] = ["multiple_or_ambiguous_bottles_in_single_bottle_demo"]
    selection["limitations"] = [
        "SINGLE_BOTTLE_DEMO_DOES_NOT_AUTO_SELECT_AMONG_MULTIPLE_BOTTLES",
        "CURRENT_RGBD_CANDIDATES_REMAIN_DIAGNOSTIC_ONLY",
    ]
    return selection


def match_yolo_detection_to_pose(
    detection,
    poses,
    *,
    iou_threshold=0.01,
    center_ratio=0.60,
    min_center_distance_px=24.0,
):
    """Return the best RGB-D pose index for a YOLO box, or None when spatially unrelated."""
    detection_bbox = (detection or {}).get("bbox_xyxy")
    detection_center = bbox_center_xy(detection_bbox)
    if detection_center is None:
        return None
    try:
        x1, y1, x2, y2 = [float(value) for value in detection_bbox[:4]]
    except (TypeError, ValueError):
        return None
    center_limit = max(
        float(min_center_distance_px),
        float(center_ratio) * min(x2 - x1, y2 - y1),
    )
    matches = []
    for index, pose in enumerate(poses or []):
        pose_bbox = geometry_bbox_xyxy(pose)
        pose_center = point_or_none((pose or {}).get("center_px"))
        if pose_center is None:
            pose_center = bbox_center_xy(pose_bbox)
        if pose_center is None:
            continue
        iou = bbox_iou_xyxy(detection_bbox, pose_bbox)
        center_distance = float(np.linalg.norm(pose_center - detection_center))
        if iou >= float(iou_threshold) or center_distance <= center_limit:
            matches.append((iou, -center_distance, index))
    return max(matches)[2] if matches else None


def detect_bottle_poses_with_yolo_trigger(
    rgb,
    depth,
    intrinsics=None,
    lock_manager=None,
    profiler=None,
    *,
    force_full_resolution=False,
):
    """Fuse pre-lock YOLO semantics with authoritative RGB-D candidates."""
    yolo_report = yolo_report_defaults()
    locked = bool(lock_manager and lock_manager.status() == "LOCKED")
    use_yolo = bool(USE_YOLO_BOTTLE_TRIGGER and not locked)
    force_full_confirmation = bool(
        not locked
        and (
            force_full_resolution
            or prelock_full_resolution_confirmation_due(lock_manager)
        )
    )
    precomputed_rgbd = None
    precomputed_rgbd_error = None
    precomputed_rgbd_resolution = None
    if use_yolo and SINGLE_BOTTLE_DEMO_MODE and FAST_FINAL_DEMO_MODE:
        precomputed_rgbd, precomputed_rgbd_error, precomputed_rgbd_resolution = (
            detect_prelock_rgbd_poses(
                rgb,
                depth,
                intrinsics=intrinsics,
                force_full_resolution=force_full_confirmation,
            )
        )
        if profiler:
            profiler.mark(
                "bottle_detection_opencv_depth_scaled_primary"
                if precomputed_rgbd_resolution == "scaled"
                else "bottle_detection_opencv_depth_primary"
            )
        one_pose = precomputed_rgbd[0] if len(precomputed_rgbd or []) == 1 else None
        rgbd_confident = bool(
            one_pose is not None
            and float(one_pose.get("detection_confidence", 0.0) or 0.0)
            >= PRELOCK_RGBD_SKIP_YOLO_CONFIDENCE
            and float(one_pose.get("depth_confidence", 0.0) or 0.0) >= 0.60
            and first_number(one_pose.get("depth_median_mm")) is not None
        )
        if rgbd_confident:
            one_pose["detection_source"] = "opencv_depth_primary_yolo_not_needed"
            one_pose["yolo_semantic_match"] = None
            yolo_report.update({
                "yolo_enabled": True,
                "yolo_runtime_state": "PRELOCK_SKIPPED_CONFIDENT_SINGLE_RGBD",
                "yolo_rgbd_fusion_mode": "RGBD_PRIMARY_YOLO_FALLBACK_ONLY",
                "rgbd_candidate_count": 1,
                "fused_pose_count": 1,
                "detection_source": "opencv_depth_primary",
                "rgbd_search_resolution": precomputed_rgbd_resolution,
            })
            return precomputed_rgbd, precomputed_rgbd_error, yolo_report
    if not use_yolo:
        if locked:
            # Return raw current candidates here. evaluate_frame owns the one
            # identity-match decision and may transition an expired
            # single-bottle lock into a new, fully gated lock attempt.
            poses, error = detect_bottle_poses(rgb, depth, intrinsics=intrinsics)
            rgbd_search_resolution = "full_resolution_locked_recovery"
        else:
            poses, error, rgbd_search_resolution = detect_prelock_rgbd_poses(
                rgb,
                depth,
                intrinsics=intrinsics,
                force_full_resolution=force_full_confirmation,
            )
        for pose in poses:
            pose["detection_source"] = "opencv_depth_fallback"
        if profiler:
            profiler.mark(
                "bottle_detection_opencv_depth_scaled"
                if rgbd_search_resolution == "scaled"
                else "bottle_detection_opencv_depth"
            )
        yolo_report["yolo_enabled"] = bool(USE_YOLO_BOTTLE_TRIGGER)
        yolo_report["detection_source"] = "opencv_depth_fallback"
        yolo_report["rgbd_search_resolution"] = rgbd_search_resolution
        yolo_report["yolo_runtime_state"] = "SKIPPED_POST_LOCK_FAST_RGBD_TRACKING" if locked else "DISABLED"
        if locked and YOLO_DETECTOR is not None:
            yolo_report["yolo_available"] = bool(getattr(YOLO_DETECTOR, "available", False))
            yolo_report["yolo_model_path"] = getattr(YOLO_DETECTOR, "model_path", None)
            yolo_report["yolo_model_backend"] = getattr(YOLO_DETECTOR, "model_backend", None)
            yolo_report["yolo_unavailable_reason"] = getattr(YOLO_DETECTOR, "unavailable_reason", None)
        return poses, error, yolo_report

    detector = get_yolo_detector()
    yolo = detector.detect(rgb)
    detections = list(yolo.get("detections") or [])
    yolo_report.update(
        {
            "yolo_enabled": True,
            "yolo_available": bool(yolo.get("yolo_available")),
            "yolo_detected": bool(yolo.get("yolo_detected")),
            "yolo_model_path": yolo.get("yolo_model_path"),
            "yolo_model_backend": yolo.get("yolo_model_backend"),
            "yolo_inference_ms": yolo.get("yolo_inference_ms"),
            "yolo_confidence": yolo.get("confidence"),
            "yolo_bbox_xyxy": yolo.get("bbox_xyxy"),
            "yolo_bbox_xywh": yolo.get("bbox_xywh"),
            "yolo_class_name": yolo.get("class_name"),
            "yolo_detection_count": len(detections),
            "yolo_detections": detections,
            "detection_source": yolo.get("detection_source", "yolo"),
            "yolo_unavailable_reason": yolo.get("yolo_unavailable_reason"),
            "yolo_runtime_state": "PRELOCK_INFERENCE",
        }
    )
    if profiler:
        profiler.mark("yolo_bottle_trigger")
    if not yolo.get("yolo_available"):
        yolo_report["yolo_runtime_state"] = "PRELOCK_FALLBACK_MODEL_UNAVAILABLE"
        if precomputed_rgbd is not None:
            poses = precomputed_rgbd
            error = precomputed_rgbd_error
            rgbd_search_resolution = precomputed_rgbd_resolution
        else:
            poses, error, rgbd_search_resolution = detect_prelock_rgbd_poses(
                rgb,
                depth,
                intrinsics=intrinsics,
                force_full_resolution=force_full_confirmation,
            )
        for pose in poses:
            pose["detection_source"] = pose.get("detection_source", "opencv_depth_fallback")
        yolo_report["rgbd_search_resolution"] = rgbd_search_resolution
        if profiler:
            profiler.mark(
                "bottle_detection_opencv_depth_fallback_scaled"
                if rgbd_search_resolution == "scaled"
                else "bottle_detection_opencv_depth_fallback"
            )
        return poses, error, yolo_report

    if precomputed_rgbd is not None:
        poses = precomputed_rgbd
        rgbd_error = precomputed_rgbd_error
        rgbd_search_resolution = precomputed_rgbd_resolution
    else:
        poses, rgbd_error, rgbd_search_resolution = detect_prelock_rgbd_poses(
            rgb,
            depth,
            intrinsics=intrinsics,
            force_full_resolution=force_full_confirmation,
        )
    for pose in poses:
        pose["detection_source"] = "opencv_depth_supplemental_yolo_missed"
        pose["yolo_semantic_match"] = False
    yolo_report.update(
        {
            "yolo_rgbd_fusion_mode": "ADDITIVE_SEMANTIC_PROPOSALS_RGBD_GATES_AUTHORITATIVE",
            "rgbd_candidate_count": len(poses),
            "detection_source": "yolo_rgbd_fused",
            "rgbd_search_resolution": rgbd_search_resolution,
        }
    )
    if not yolo.get("yolo_detected"):
        yolo_report["yolo_runtime_state"] = "PRELOCK_NO_SEMANTIC_MATCH_RGBD_RETAINED"
        yolo_report["fused_pose_count"] = len(poses)
        if profiler:
            profiler.mark(
                "bottle_detection_rgbd_yolo_no_match_scaled"
                if rgbd_search_resolution == "scaled"
                else "bottle_detection_rgbd_yolo_no_match"
            )
        return poses, rgbd_error, yolo_report

    detection_list = detections or [yolo]
    detection_matches = [
        match_yolo_detection_to_pose(detection, poses)
        for detection in detection_list
    ]
    match_counts = {
        matched_index: detection_matches.count(matched_index)
        for matched_index in set(detection_matches)
        if matched_index is not None
    }
    ambiguous_merged_indexes = {
        matched_index
        for matched_index, count in match_counts.items()
        if count > 1
    }
    matched_rgbd_indexes = set()
    unmatched_detection_count = 0
    roi_pose_count = 0
    split_replacement_count = 0
    roi_proposals: list[tuple[int | None, dict]] = []
    errors = []
    for detection, matched_index in zip(detection_list, detection_matches):
        if matched_index is not None and matched_index not in ambiguous_merged_indexes:
            pose = poses[matched_index]
            pose["detection_source"] = "yolo_confirmed_opencv_depth"
            pose["yolo_bbox_xyxy"] = detection.get("bbox_xyxy")
            pose["yolo_confidence"] = detection.get("confidence")
            pose["yolo_class_name"] = detection.get("class_name")
            pose["yolo_semantic_match"] = True
            matched_rgbd_indexes.add(matched_index)
            continue

        unmatched_detection_count += 1
        roi_expand = min(float(YOLO_ROI_EXPAND_RATIO), 0.05) if matched_index in ambiguous_merged_indexes else YOLO_ROI_EXPAND_RATIO
        roi = expand_bbox_xyxy(detection.get("bbox_xyxy"), rgb.shape, roi_expand)
        if roi is None:
            errors.append("YOLO bottle bbox was too small or invalid.")
            continue
        x1, y1, x2, y2 = roi
        roi_intrinsics = {
            **(intrinsics or {}),
            "cx": None if (intrinsics or {}).get("cx") is None else float(intrinsics["cx"]) - x1,
            "cy": None if (intrinsics or {}).get("cy") is None else float(intrinsics["cy"]) - y1,
        }
        roi_pose, error = detect_bottle_pose(
            rgb[y1:y2, x1:x2],
            depth[y1:y2, x1:x2],
            intrinsics=roi_intrinsics,
        )
        if roi_pose is None:
            errors.append(error or "RGB-D bottle pose failed inside YOLO ROI.")
            continue
        roi_pose = offset_pose_to_full(roi_pose, rgb.shape, roi)
        roi_pose["detection_source"] = "yolo_roi_opencv_depth"
        roi_pose["yolo_bbox_xyxy"] = detection.get("bbox_xyxy")
        roi_pose["yolo_confidence"] = detection.get("confidence")
        roi_pose["yolo_class_name"] = detection.get("class_name")
        roi_pose["yolo_semantic_match"] = True
        roi_proposals.append((matched_index, roi_pose))

    for matched_index in ambiguous_merged_indexes:
        replacements = [
            proposal
            for proposal_match, proposal in roi_proposals
            if proposal_match == matched_index
        ]
        centers = [
            point_or_none(proposal.get("center_px"))
            for proposal in replacements
        ]
        centers = [center for center in centers if center is not None]
        distinct = bool(
            len(centers) >= 2
            and max(
                float(np.linalg.norm(left - right))
                for index, left in enumerate(centers)
                for right in centers[index + 1 :]
            ) >= 10.0
        )
        if len(replacements) >= 2 and distinct:
            poses[matched_index]["_replace_ambiguous_merged_rgbd_pose"] = True
            for replacement in replacements:
                replacement["detection_source"] = "yolo_split_rgbd_validated"
                replacement["split_from_ambiguous_rgbd_candidate"] = True
                poses.append(replacement)
            matched_rgbd_indexes.add(matched_index)
            roi_pose_count += len(replacements)
            split_replacement_count += len(replacements)
        else:
            poses[matched_index]["yolo_split_status"] = "INCOMPLETE_KEEP_UNSPLIT_RGBD_CANDIDATE"
            poses[matched_index]["yolo_split_proposal_count"] = len(replacements)

    poses = [
        pose
        for pose in poses
        if not pose.pop("_replace_ambiguous_merged_rgbd_pose", False)
    ]
    unmatched_proposals = [
        proposal
        for proposal_match, proposal in roi_proposals
        if proposal_match is None
    ]
    poses.extend(unmatched_proposals)
    roi_pose_count += len(unmatched_proposals)
    if profiler:
        profiler.mark("bottle_detection_yolo_rgbd_fusion")
    for index, pose in enumerate(sorted(poses, key=lambda item: float(item["center_px"][0])), start=1):
        pose["target_id"] = f"bottle_{index:02d}"
        pose["target_id_scope"] = "FRAME_LOCAL_UNTIL_TARGET_LOCK"
        pose["detected_bottle_count"] = len(poses)
    yolo_report.update(
        {
            "yolo_rois_xyxy": [item.get("bbox_xyxy") for item in detections],
            "yolo_matched_rgbd_count": len(matched_rgbd_indexes),
            "yolo_unmatched_detection_count": unmatched_detection_count,
            "yolo_roi_pose_count": roi_pose_count,
            "yolo_ambiguous_merged_rgbd_count": len(ambiguous_merged_indexes),
            "yolo_split_replacement_count": split_replacement_count,
            "fused_pose_count": len(poses),
            "yolo_runtime_state": "PRELOCK_FUSED",
        }
    )
    error = None if poses else (errors[0] if errors else rgbd_error or "No RGB-D-valid bottle pose found.")
    return poses, error, yolo_report


def detect_bottle_pose_with_yolo_trigger(rgb, depth, intrinsics=None, lock_manager=None, profiler=None):
    poses, error, yolo_report = detect_bottle_poses_with_yolo_trigger(
        rgb,
        depth,
        intrinsics=intrinsics,
        lock_manager=lock_manager,
        profiler=profiler,
    )
    return (poses[0] if poses else None), error, yolo_report


def attach_yolo_report(report, yolo_report):
    yolo_report = yolo_report or yolo_report_defaults(enabled=False)
    report["yolo_enabled"] = bool(yolo_report.get("yolo_enabled", False))
    report["yolo_available"] = bool(yolo_report.get("yolo_available", False))
    report["yolo_detected"] = bool(yolo_report.get("yolo_detected", False))
    report["yolo_model_path"] = yolo_report.get("yolo_model_path")
    report["yolo_model_backend"] = yolo_report.get("yolo_model_backend")
    report["yolo_inference_ms"] = yolo_report.get("yolo_inference_ms")
    report["yolo_confidence"] = yolo_report.get("yolo_confidence")
    report["yolo_bbox_xyxy"] = yolo_report.get("yolo_bbox_xyxy")
    report["yolo_bbox_xywh"] = yolo_report.get("yolo_bbox_xywh")
    report["yolo_class_name"] = yolo_report.get("yolo_class_name")
    report["yolo_roi_xyxy"] = yolo_report.get("yolo_roi_xyxy")
    report["yolo_rois_xyxy"] = yolo_report.get("yolo_rois_xyxy") or []
    report["yolo_detection_count"] = int(yolo_report.get("yolo_detection_count", 0) or 0)
    report["detection_source"] = yolo_report.get("detection_source")
    report["yolo_unavailable_reason"] = yolo_report.get("yolo_unavailable_reason")
    report["yolo_runtime_state"] = yolo_report.get("yolo_runtime_state")
    report["yolo_rgbd_fusion_mode"] = yolo_report.get("yolo_rgbd_fusion_mode")
    report["rgbd_search_resolution"] = yolo_report.get("rgbd_search_resolution")
    report["prelock_full_confirmation_active"] = bool(
        yolo_report.get("prelock_full_confirmation_active", False)
    )
    report["prelock_full_confirmation_state"] = yolo_report.get(
        "prelock_full_confirmation_state"
    )
    report["prelock_full_confirmation_frames"] = int(
        yolo_report.get("prelock_full_confirmation_frames", 0) or 0
    )
    report["prelock_full_confirmation_misses"] = int(
        yolo_report.get("prelock_full_confirmation_misses", 0) or 0
    )
    report["prelock_full_confirmation_last_rejection_reasons"] = list(
        yolo_report.get("prelock_full_confirmation_last_rejection_reasons") or []
    )
    report["prelock_full_confirmation_last_rejection_metrics"] = json_safe(
        yolo_report.get("prelock_full_confirmation_last_rejection_metrics") or {}
    )
    report["lost_target_reacquisition_status"] = yolo_report.get(
        "lost_target_reacquisition_status"
    )
    report["rgbd_candidate_count"] = int(yolo_report.get("rgbd_candidate_count", 0) or 0)
    report["yolo_matched_rgbd_count"] = int(yolo_report.get("yolo_matched_rgbd_count", 0) or 0)
    report["yolo_unmatched_detection_count"] = int(yolo_report.get("yolo_unmatched_detection_count", 0) or 0)
    report["yolo_roi_pose_count"] = int(yolo_report.get("yolo_roi_pose_count", 0) or 0)
    report["yolo_ambiguous_merged_rgbd_count"] = int(yolo_report.get("yolo_ambiguous_merged_rgbd_count", 0) or 0)
    report["yolo_split_replacement_count"] = int(yolo_report.get("yolo_split_replacement_count", 0) or 0)
    report["fused_pose_count"] = int(yolo_report.get("fused_pose_count", 0) or 0)
    return report


def log_grasp_attempt(attempt):
    append_jsonl(OUTPUT_DIR / "grasp_attempt_log.jsonl", attempt)


def selected_body_fraction_from_report(report):
    plan = report.get("planned_contacts") or {}
    selected = report.get("selected_grasp") or plan.get("selected_contact_pair") or {}
    return selected.get("body_fraction", plan.get("body_fraction"))


def trace_locked_target_frame(report):
    global LAST_TARGET_LOCK_TRACE_TIME
    lock = report.get("target_lock") or {}
    locked = lock.get("locked_target") or {}
    plan = report.get("planned_contacts") or {}
    tracking = lock.get("current_tracked_target") or {}
    smoothed = report.get("smoothed_realtime_values") or lock.get("smoothed_tracking_values") or {}
    target_clamp = report.get("target_clamp") or lock.get("target_clamp") or {}
    contact_model = report.get("bottle_contact_model") or lock.get("bottle_contact_model") or {}
    selected_fraction = selected_body_fraction_from_report(report)
    locked_fraction = lock.get("locked_body_fraction", locked.get("locked_body_fraction"))
    current_fraction = plan.get("body_fraction", tracking.get("locked_body_fraction"))
    clamp_source = report.get("clamp_source") or lock.get("clamp_source") or target_clamp.get("clamp_source")
    gui_draw_source = lock.get("gui_draw_source") or clamp_source or "stale/unknown"
    decision_source = lock.get("decision_source") or clamp_source
    guide_left = report.get("contact_guide_left_px") or lock.get("contact_guide_left_px") or (contact_model.get("left_contact_patch") or {}).get("center_px")
    guide_right = report.get("contact_guide_right_px") or lock.get("contact_guide_right_px") or (contact_model.get("right_contact_patch") or {}).get("center_px")
    clamp_left = report.get("clamp_patch_left_center_px") or lock.get("clamp_patch_left_center_px") or (target_clamp.get("left_clamp_patch") or {}).get("center_px")
    clamp_right = report.get("clamp_patch_right_center_px") or lock.get("clamp_patch_right_center_px") or (target_clamp.get("right_clamp_patch") or {}).get("center_px")
    status = lock.get("target_status")
    locked_or_tracking = status in {"LOCKED", "TRACKING", "LOW_CONFIDENCE"}
    expected_fraction = locked.get("locked_body_fraction_at_lock", locked.get("locked_body_fraction", locked_fraction))
    warnings = []
    allowed_clamp_sources = {
        "locked_target",
        "current_bottle_side_edges",
        "partial_rgbd_hand_occlusion_rigid_motion_estimate",
        "partial_rgbd_bounded_rigid_motion_estimate",
        "locked_bottle_local_3d_reprojection",
        "held_last_valid_bottle_local_3d_projection",
        "estimated_local_patch_from_last_valid_3d",
        "unavailable_no_current_3d_projection",
    }
    if locked_or_tracking:
        if selected_fraction is not None and not nearly_equal(
            selected_fraction,
            expected_fraction,
            tol=BODY_FRACTION_EQUIVALENCE_TOLERANCE,
        ):
            warnings.append("BUG: locked target overwritten")
        if not nearly_equal(locked_fraction, expected_fraction):
            warnings.append("BUG: locked target overwritten")
        if clamp_source is not None and clamp_source not in allowed_clamp_sources:
            warnings.append("BUG: locked target overwritten")
        if gui_draw_source == "current_best_candidate":
            warnings.append("BUG: GUI using recomputed target instead of locked target")
    if locked_or_tracking and current_fraction is not None and not nearly_equal(
        current_fraction,
        expected_fraction,
        tol=BODY_FRACTION_EQUIVALENCE_TOLERANCE,
    ):
        warnings.append("BUG: locked target overwritten")

    diagnostics = report.get("grasp_target_3d_diagnostics") or {}
    compact_diagnostics = {
        key: json_safe(diagnostics.get(key))
        for key in (
            "projection_mode",
            "projection_valid",
            "projection_invalid_reason",
            "identity_measurement_current",
            "contact_patch_tracking_ok",
            "distance_measurement_valid",
        )
        if diagnostics.get(key) is not None
    }
    trace = {
        "frame_id": report.get("frame_id"),
        "timestamp": report.get("timestamp", utc_now()),
        "writer_session_id": report.get("writer_session_id"),
        "monotonic_frame_counter": report.get("monotonic_frame_counter"),
        # This is a transition/debug trace, not a per-frame artifact archive.
        # Dense diagnostics previously produced multi-GB files during a demo.
        "grasp_target_3d_diagnostics": compact_diagnostics,
        "target_status": status,
        "bottle_target_id": locked.get("bottle_target_id") or lock.get("bottle_target_id"),
        "attempt_id": lock.get("attempt_id") or locked.get("attempt_id"),
        "lock_frame_id": lock.get("lock_frame_id") or locked.get("lock_frame_id"),
        "identity_tracking_ok": lock.get("identity_tracking_ok"),
        "identity_measurement_current": lock.get("identity_measurement_current"),
        "identity_occlusion_hold_active": lock.get("identity_occlusion_hold_active"),
        "identity_occlusion_hold_frames": lock.get("identity_occlusion_hold_frames"),
        "identity_occlusion_hold_expired": lock.get("identity_occlusion_hold_expired"),
        "state": report.get("state"),
        "distance_to_bottle_mm": first_number(
            report.get("distance_to_bottle_mm"),
            report.get("actionable_distance_mm"),
            report.get("contact_band_depth_mm"),
        ),
        "distance_measurement_valid": report.get("distance_measurement_valid") is True,
        "distance_confidence": first_number(report.get("distance_confidence")),
        "grasp_band_drift_px": first_number(
            report.get("grasp_band_drift_px"),
            lock.get("grasp_band_drift_px"),
        ),
        "grasp_band_state": lock.get("grasp_band_state"),
        "band_drift_state": lock.get("band_drift_state"),
        "grasp_band_current": lock.get("grasp_band_current"),
        "grasp_band_held": lock.get("grasp_band_held"),
        "grasp_band_stale": lock.get("grasp_band_stale"),
        "grasp_band_relock_required": lock.get("grasp_band_relock_required"),
        "locked_projection_mode": lock.get("locked_projection_mode"),
        "projection_valid": lock.get("projection_valid"),
        "sticky_lock_waiting_reacquisition": lock.get(
            "sticky_lock_waiting_reacquisition"
        ),
        "sticky_lock_dropout_frames": lock.get("sticky_lock_dropout_frames"),
        "sticky_lock_preserved_attempt_id": lock.get(
            "sticky_lock_preserved_attempt_id"
        ),
        "full_bottle_visible": report.get("full_bottle_visible"),
        "locked_patch_visible": lock.get("locked_patch_visible", report.get("locked_patch_visible")),
        "locked_body_fraction": locked_fraction,
        "current_body_fraction_used": current_fraction,
        "selected_candidate_body_fraction": selected_fraction,
        "bottle_center_raw": (report.get("bottle_geometry") or {}).get("center_px"),
        "bottle_center_smoothed": smoothed.get("bottle_center_px"),
        "bottle_contact_guide_left": guide_left,
        "bottle_contact_guide_right": guide_right,
        "clamp_patch_left_center": clamp_left,
        "clamp_patch_right_center": clamp_right,
        "clamp_source": clamp_source,
        "band_source": report.get("band_source") or target_clamp.get("band_source"),
        "edge_source": report.get("edge_source") or target_clamp.get("edge_source"),
        "gui_draw_source": gui_draw_source,
        "decision_source": decision_source,
        "clamp_vs_guide_error_left_px": report.get("clamp_vs_guide_error_left_px", lock.get("clamp_vs_guide_error_left_px", point_distance_px(clamp_left, guide_left))),
        "clamp_vs_guide_error_right_px": report.get("clamp_vs_guide_error_right_px", lock.get("clamp_vs_guide_error_right_px", point_distance_px(clamp_right, guide_right))),
        "ready_blockers": report.get("ready_blockers") or lock.get("ready_blockers") or [],
        "recommended_action": report.get("recommended_action"),
        "warnings": warnings,
    }
    if warnings:
        for warning in dict.fromkeys(warnings):
            print(warning, flush=True)
        report.setdefault("warnings", [])
        report["warnings"] = list(report["warnings"]) + [w for w in dict.fromkeys(warnings) if w not in report["warnings"]]
    now = time.monotonic()
    if (not FAST_FINAL_DEMO_MODE) or now - LAST_TARGET_LOCK_TRACE_TIME >= TARGET_LOCK_TRACE_INTERVAL_SEC:
        LAST_TARGET_LOCK_TRACE_TIME = now
        append_target_lock_trace(trace)
    report["target_lock_trace"] = trace
    return trace


def coordinate_entry(value, frame, updated, source):
    return {
        "value": json_safe(value),
        "coordinate_frame": frame,
        "updated_this_frame": bool(updated),
        "source": source,
    }


def append_patch_coordinate_trace(report, rgb_shape, overlay_shape=None):
    global PATCH_COORD_TRACE_COUNT
    if PATCH_COORD_TRACE_COUNT >= PATCH_COORD_TRACE_MAX_FRAMES:
        return
    lock = report.get("target_lock") or {}
    tracking = lock.get("current_tracked_target") or {}
    locked = lock.get("locked_target") or {}
    target_clamp = report.get("target_clamp") or lock.get("target_clamp") or tracking.get("target_clamp") or {}
    locked_model_clamp = (
        tracking.get("locked_bottle_reference_clamp_zone")
        or derive_target_clamp_from_contact_model(locked.get("bottle_contact_model") or {}, source="locked_target")
    )
    fixed_clamp = tracking.get("fixed_camera_clamp_zone") or locked.get("fixed_clamp_zone") or locked.get("locked_clamp_region_px")
    locked_model_bbox = patch_bbox_from_polygons(
        [
            (locked_model_clamp.get("left_clamp_patch") or {}).get("polygon"),
            (locked_model_clamp.get("right_clamp_patch") or {}).get("polygon"),
        ],
        rgb_shape,
    )
    fixed_bbox = patch_bbox_from_polygons(
        [
            ((fixed_clamp or {}).get("left_clamp_patch") or {}).get("polygon"),
            ((fixed_clamp or {}).get("right_clamp_patch") or {}).get("polygon"),
        ],
        rgb_shape,
    )
    bottle_geometry = report.get("bottle_geometry") or {}
    patch_bbox = tracking.get("patch_bbox_current_px")
    patch_center = tracking.get("current_patch_center_px") or target_clamp.get("clamp_center_px")
    tracked_center = tracking.get("current_tracked_center_px")
    trace = {
        "timestamp": utc_now(),
        "frame_id": report.get("frame_id"),
        "writer_session_id": report.get("writer_session_id"),
        "lock_frame_id": lock.get("lock_frame_id") or locked.get("lock_frame_id"),
        "attempt_id": lock.get("attempt_id") or locked.get("attempt_id"),
        "bottle_target_id": locked.get("bottle_target_id") or lock.get("bottle_target_id"),
        "active_branch": report.get("overlay_mode") or report.get("state_transition_reason"),
        "clamp_source": report.get("clamp_source") or lock.get("clamp_source") or target_clamp.get("clamp_source"),
        "rgb_frame_size": list(rgb_shape[:2]) if rgb_shape is not None else None,
        "displayed_overlay_size": list(overlay_shape[:2]) if overlay_shape is not None else list(rgb_shape[:2]) if rgb_shape is not None else None,
        "resize_scale": coordinate_entry([1.0, 1.0], "display_equals_full_frame_for_written_overlay", True, "draw_fast_overlay"),
        "crop_roi_origin": coordinate_entry([0, 0], "full-frame", True, "no_display_crop"),
        "detected_or_locked_bottle_bbox": coordinate_entry(
            bottle_geometry.get("bottle_extent_bbox_xyxy") or bottle_geometry.get("bbox_xyxy") or bottle_geometry.get("bbox_xywh"),
            "full-frame coordinate",
            bool(bottle_geometry.get("updated_every_frame")),
            "bottle_geometry full bottle extent",
        ),
        "contact_tracking_bbox": coordinate_entry(
            bottle_geometry.get("contact_tracking_bbox_xyxy") or tracking.get("current_tracked_bbox_xyxy"),
            "full-frame coordinate",
            True,
            "local contact/depth ROI bbox, not bottle extent",
        ),
        "current_tracked_bbox": coordinate_entry(
            tracking.get("current_tracked_bbox_xyxy"),
            "full-frame coordinate",
            True,
            "local_locked_patch_tracking.current_tracked_bbox_xyxy",
        ),
        "displayed_green_bottle_extent_roi": coordinate_entry(
            expand_bbox_xyxy_local(
                bottle_geometry.get("bottle_extent_bbox_xyxy") or bottle_geometry.get("bbox_xyxy"),
                rgb_shape,
                expand_ratio=0.12,
                min_pad_px=18.0,
            ),
            "full-frame coordinate",
            True,
            "expanded current bottle extent drawn as green ROI",
        ),
        "current_tracked_center": coordinate_entry(
            tracked_center,
            "full-frame coordinate",
            True,
            "local_locked_patch_tracking.current_tracked_center_px",
        ),
        "original_locked_bottle_bbox": coordinate_entry(
            locked_model_bbox,
            "full-frame coordinate",
            False,
            "locked_target.bottle_contact_model at lock",
        ),
        "original_fixed_camera_clamp_bbox": coordinate_entry(
            fixed_bbox,
            "full-frame coordinate",
            False,
            "locked_target.fixed_clamp_zone at lock",
        ),
        "original_locked_center": coordinate_entry(
            tracking.get("locked_reference_center_px") or target_clamp_center(locked_model_clamp),
            "full-frame coordinate",
            False,
            "locked bottle contact center",
        ),
        "magenta_patch_bbox": coordinate_entry(
            patch_bbox,
            "full-frame coordinate",
            True,
            "target_clamp current projected patch bbox",
        ),
        "magenta_patch_center": coordinate_entry(
            patch_center,
            "full-frame coordinate",
            True,
            "target_clamp current projected patch center",
        ),
        "left_contact_patch_coordinates": coordinate_entry(
            (target_clamp.get("left_clamp_patch") or {}).get("polygon"),
            "full-frame coordinate",
            True,
            "target_clamp.left_clamp_patch",
        ),
        "right_contact_patch_coordinates": coordinate_entry(
            (target_clamp.get("right_clamp_patch") or {}).get("polygon"),
            "full-frame coordinate",
            True,
            "target_clamp.right_clamp_patch",
        ),
        "depth_roi_coordinates": coordinate_entry(
            tracking.get("local_patch_roi_xyxy") or tracking.get("local_motion_search_roi_xyxy"),
            "full-frame coordinate",
            True,
            "ROI used for local depth patch evidence",
        ),
        "delta_patch_from_current_center_px": coordinate_entry(
            (point_or_none(patch_center) - point_or_none(tracked_center)).tolist()
            if point_or_none(patch_center) is not None and point_or_none(tracked_center) is not None
            else None,
            "full-frame delta",
            True,
            "magenta patch center minus current tracked center",
        ),
        "diagnosis_hint": tracking.get("clamp_base_source"),
    }
    append_jsonl(PATCH_COORD_TRACE_PATH, trace)
    PATCH_COORD_TRACE_COUNT += 1
    report["patch_coordinate_trace_path"] = str(PATCH_COORD_TRACE_PATH)


def validate_freeze_trace_sequence(entries, tolerance_px=5.0):
    warnings = []
    locked_entries = [e for e in entries if e.get("target_status") in {"LOCKED", "TRACKING"}]
    if not locked_entries:
        return warnings
    locked_fraction = locked_entries[0].get("locked_body_fraction")
    previous = locked_entries[0]
    for entry in locked_entries:
        frame_id = entry.get("frame_id")
        if not nearly_equal(entry.get("locked_body_fraction"), locked_fraction):
            warnings.append(f"BUG: locked target overwritten at frame {frame_id}: locked_body_fraction changed")
        for side in ("left", "right"):
            key = f"clamp_patch_{side}_center"
            clamp_move = point_distance_px(previous.get(key), entry.get(key))
            center_move = point_distance_px(previous.get("bottle_center_raw"), entry.get("bottle_center_raw"))
            if clamp_move is None or center_move is None:
                continue
            if clamp_move > center_move + float(tolerance_px):
                warnings.append(
                    f"WARNING: clamp patch {side} moved {clamp_move:.1f}px while bottle center moved {center_move:.1f}px at frame {frame_id}"
                )
        previous = entry
    return warnings


def normalize_depth_preview(depth):
    valid = valid_depth_mask(depth)
    if np.any(valid):
        lo, hi = np.percentile(depth[valid], [5, 95])
        scaled = np.clip((depth.astype(float) - lo) / max(hi - lo, 1.0), 0.0, 1.0)
    else:
        scaled = np.zeros_like(depth, dtype=float)
    gray = (scaled * 255).astype(np.uint8)
    return cv2.cvtColor(cv2.applyColorMap(gray, cv2.COLORMAP_VIRIDIS), cv2.COLOR_BGR2RGB)


def global_depth_stats(depth):
    if depth is None:
        return {}
    return compute_depth_stats(depth, np.ones(depth.shape[:2], dtype=np.uint8))


def build_depth_context(depth_raw, mask=None):
    depth_smooth = smooth_depth_pipeline(depth_raw)
    raw_stats = compute_depth_stats(depth_raw, mask) if mask is not None else global_depth_stats(depth_raw)
    smooth_stats = compute_depth_stats(depth_smooth, mask) if mask is not None else global_depth_stats(depth_smooth)
    return {
        "depth_raw": depth_raw,
        "depth_smooth": depth_smooth,
        "report": {
            "depth_smoothing_enabled": bool(USE_DEPTH_SMOOTHING),
            "depth_smoothing_pipeline": {
                "median_kernel": int(DEPTH_MEDIAN_KERNEL),
                "bilateral_enabled": bool(DEPTH_BILATERAL_ENABLED),
                "patch_size_px": int(DEPTH_PATCH_SIZE),
                "valid_min_mm": int(DEPTH_VALID_MIN_MM),
                "valid_max_mm": int(DEPTH_VALID_MAX_MM),
                "notes": "Raw depth is preserved; smoothed depth is used for live preview, mask cleanup support, and robust contact patch measurements.",
            },
            "raw_depth": raw_stats,
            "smoothed_depth": smooth_stats,
        },
    }


def attach_depth_report(report, depth_context=None, plan=None):
    if not depth_context:
        return report
    depth_report = depth_context.get("report", {})
    report["depth_smoothing"] = depth_report
    depth_stats = dict(report.get("depth_stats", {}))
    depth_stats.update({
        "depth_smoothing_enabled": depth_report.get("depth_smoothing_enabled", USE_DEPTH_SMOOTHING),
        "raw_depth_median_mm": (depth_report.get("raw_depth") or {}).get("median_mm"),
        "smoothed_depth_median_mm": (depth_report.get("smoothed_depth") or {}).get("median_mm"),
        "raw_depth_valid_ratio": (depth_report.get("raw_depth") or {}).get("valid_ratio"),
        "smoothed_depth_valid_ratio": (depth_report.get("smoothed_depth") or {}).get("valid_ratio"),
    })
    if plan:
        depth_stats["left_patch_depth_stats"] = plan.get("left_depth_stats")
        depth_stats["right_patch_depth_stats"] = plan.get("right_depth_stats")
        left_ratio = float((plan.get("left_depth_stats") or {}).get("valid_ratio", 0.0) or 0.0)
        right_ratio = float((plan.get("right_depth_stats") or {}).get("valid_ratio", 0.0) or 0.0)
        depth_stats["patch_depth_confidence"] = clamp_0_100(100.0 * min(left_ratio, right_ratio))
    report["depth_stats"] = depth_stats
    return report


