    locked_bottle_target_id = next(
        (value for value in (locked.get("bottle_target_id"), lock.get("bottle_target_id"), report.get("locked_bottle_target_id")) if value is not None),
        None,
    )
    lock_attempt_id = next(
        (value for value in (lock.get("attempt_id"), locked.get("attempt_id"), report.get("lock_attempt_id"), report.get("attempt_id")) if value is not None),
        None,
    )
    target_clamp = report.get("target_clamp") or lock.get("target_clamp") or tracking.get("target_clamp") or {}
    bottle_geometry = report.get("bottle_geometry") or {}
